export const AHADEES: Hadees[] = [
  { id: 'h001', arabic: 'إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ', narrator: 'حضرت عمر بن الخطابؓ', source: 'صحیح البخاری', hadithNumber: '1', bookNumber: '1', category: 'faith', tags: ['نیت','عمل','اخلاص'],
    translations: t('إِنَّمَا الأَعْمَالُ بِالنِّيَّاتِ','اعمال کا دارومدار نیتوں پر ہے۔','Actions are judged by intentions.','اعمال به نیات بستگی دارند.','কাজের বিচার নিয়তের উপর।','عمل نيتن سان آهن.','کار کڈا نیت سرا اَنت.','اعمال د نیت پر وي.','कर्मों का निर्णय नीयत से होता है।','Ameller niyetlere göredir.','Дела оцениваются по намерениям.','行为以意图为判断标准。','行いは意図によって判断される。') },

  { id: 'h002', arabic: 'الدِّيْنُ النَّصِيحَةُ', narrator: 'حضرت تمیم الداریؓ', source: 'صحیح مسلم', hadithNumber: '55', bookNumber: '1', category: 'character', tags: ['خیرخواہی','نصیحت','دین'],
    translations: t('الدِّيْنُ النَّصِيحَةُ','دین خیرخواہی کا نام ہے۔','Religion is sincere advice.','دین نصیحت است.','দ্বীন হলো আন্তরিক উপদেশ।','دين نصيحت آهي.','دین نصیحت اِنت.','دین نصیحت دی.','धर्म शुभेच्छा है।','Din nasihatten ibarettir.','Религия — это совет.','宗教就是真诚的忠告。','宗教は誠実な助言である。') },

  { id: 'h003', arabic: 'طَلَبُ الْعِلْمِ فَرِيضَةٌ عَلَى كُلِّ مُسْلِمٍ', narrator: 'حضرت انس بن مالکؓ', source: 'سنن ابن ماجہ', hadithNumber: '224', bookNumber: '1', category: 'knowledge', tags: ['علم','تعلیم','فریضہ'],
    translations: t('طَلَبُ الْعِلْمِ فَرِيضَةٌ عَلَى كُلِّ مُسْلِمٍ','علم حاصل کرنا ہر مسلمان پر فرض ہے۔','Seeking knowledge is an obligation upon every Muslim.','طلب علم بر هر مسلمانی واجب است.','জ্ঞান অর্জন করা প্রতিটি মুসলমানের ফরজ।','علم حاصل ڪرڻ هر مسلمان تي فرض آهي.','علم گپتن هر مسلمانی پر فرض اِنت.','د علم لټون د هر مسلمان فرض دی.','ज्ञान प्राप्त करना हर मुसलमान पर फ़र्ज़ है।','İlim öğrenmek her Müslümana farzdır.','Поиск знаний — обязанность каждого мусульманина.','寻求知识是每个穆斯林的义务。','知識を求めることは全ムスリムの義務。') },

  { id: 'h004', arabic: 'خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ', narrator: 'حضرت عثمان بن عفانؓ', source: 'صحیح البخاری', hadithNumber: '5027', bookNumber: '66', category: 'knowledge', tags: ['قرآن','تعلیم','فضیلت'],
    translations: t('خَيْرُكُمْ مَنْ تَعَلَّمَ الْقُرْآنَ وَعَلَّمَهُ','تم میں سب سے بہتر وہ ہے جو قرآن سیکھے اور سکھائے۔','The best is one who learns the Quran and teaches it.','بهترین شما کسی است که قرآن بیاموزد.','তোমাদের মধ্যে সর্বোত্তম যে কুরআন শেখে ও শেখায়।','توهان مان بهترين اهو آهي جيڪو قرآن سکي.','شما را بهترین کسے اَنت که قرآن یاد گیرت.','ستاسو غوره هغه دی چې قرآن زده کړي.','तुम में सर्वश्रेष्ठ वह जो कुरआन सीखे और सिखाए।',"En hayırlınız Kur'an'ı öğrenen ve öğretendir.",'Лучший — тот, кто изучает Коран и обучает ему.','最好的人是学习并教授《古兰经》的人。','最も優れた者はクルアーンを学び教える者。') },

  { id: 'h005', arabic: 'الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ', narrator: 'حضرت عبداللہ بن عمروؓ', source: 'صحیح البخاری', hadithNumber: '10', bookNumber: '1', category: 'character', tags: ['مسلمان','اخلاق','زبان'],
    translations: t('الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ','مسلمان وہ ہے جس کی زبان و ہاتھ سے دوسرے محفوظ رہیں۔','A Muslim is one from whose tongue and hands others are safe.','مسلمان کسی است که دیگران از زبان و دستش ایمن باشند.','মুসলমান সে যার জিহ্বা ও হাত থেকে অন্যরা নিরাপদ।','مسلمان اهو آهي جنهن جي زبان ۽ هٿ کان ٻيا محفوظ هجن.','مسلمان کسے اِنت که مسلمانان از زبان و دستش ایمن بنت.','مسلمان هغه دی چې نور د هغه له ژبې او لاس نه خوندي وي.','मुसलमान वह जिसकी जीभ और हाथ से दूसरे सुरक्षित रहें।','Müslüman, diğerlerinin dilinden ve elinden güvende olduğu kişidir.','Мусульманин — тот, от чьих языка и рук другие в безопасности.','穆斯林是让他人免受其舌头和手伤害的人。','ムスリムとは他者がその舌と手から安全な者。') },

  { id: 'h006', arabic: 'إِنَّ اللَّهَ جَمِيلٌ يُحِبُّ الْجَمَالَ', narrator: 'حضرت عبداللہ بن مسعودؓ', source: 'صحیح مسلم', hadithNumber: '91', bookNumber: '1', category: 'faith', tags: ['خوبصورتی','اللہ','محبت'],
    translations: t('إِنَّ اللَّهَ جَمِيلٌ يُحِبُّ الْجَمَالَ','اللہ تعالیٰ خوبصورت ہے اور خوبصورتی کو پسند فرماتا ہے۔','Allah is Beautiful and He loves beauty.','الله زیباست و زیبایی را دوست دارد.','আল্লাহ সুন্দর এবং তিনি সৌন্দর্যকে ভালোবাসেন।','الله خوبصورت آهي ۽ خوبصورتي کي پسند ڪري ٿو.','الله زیباست و زیبایی را دوست دارد.','الله ښکلی دی او ښکلا یې خوښیږي.','अल्लाह सुंदर है और सुंदरता को पसंद करता है।','Allah güzeldir ve güzelliği sever.','Аллах Прекрасен и любит красоту.','安拉是美丽的，他喜爱美丽。','アッラーは美しく、美しさを愛される。') },

  { id: 'h007', arabic: 'اتَّقِ اللَّهَ حَيْثُمَا كُنْتَ وَأَتْبِعِ السَّيِّئَةَ الْحَسَنَةَ تَمْحُهَا', narrator: 'حضرت ابو ذرؓ و معاذؓ', source: 'سنن الترمذی', hadithNumber: '1987', bookNumber: '27', category: 'character', tags: ['تقویٰ','توبہ','نیکی'],
    translations: t('اتَّقِ اللَّهَ حَيْثُمَا كُنْتَ','جہاں بھی رہو اللہ سے ڈرو، برائی کے بعد نیکی کرو۔','Fear Allah wherever you are; follow a bad deed with a good one.','هرجا هستی از الله بترس، بدی را با نیکی محو کن.','যেখানেই থাকো আল্লাহকে ভয় করো, মন্দের পর ভালো করো।','جتي به هجو الله کان ڊڄو، برائيءَ کان پوءِ نيڪي ڪريو.','هر کجا که هستی از الله بترس.','چرته چې يې الله ووېره، بدۍ وروسته نيکي وکړه.','जहाँ भी रहो अल्लाह से डरो, बुरे के बाद अच्छा करो।','Nerede olursan ol Allah\'tan kork.','Бойся Аллаха, где бы ты ни был.','无论身在何处都要敬畏安拉。','どこにいてもアッラーを畏れよ。') },

  { id: 'h008', arabic: 'مَنْ صَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ', narrator: 'حضرت ابو ہریرہؓ', source: 'صحیح البخاری', hadithNumber: '38', bookNumber: '2', category: 'worship', tags: ['رمضان','روزہ','مغفرت'],
    translations: t('مَنْ صَامَ رَمَضَانَ إِيمَانًا وَاحْتِسَابًا','جو رمضان کے روزے ایمان و ثواب کی نیت سے رکھے اس کے گناہ معاف۔','Whoever fasts Ramadan with faith, his previous sins are forgiven.','هرکس رمضان را با ایمان روزه بگیرد گناهانش آمرزیده می‌شود.','যে রমজানে ঈমানের সাথে রোজা রাখে তার গুনাহ মাফ।','جيڪو رمضان جا روزا ايمان سان رکي، سندس گناهه معاف.','هرکه رمضان را با ایمان روزه بگیرد گناهانش بخشیده می‌شود.','چا چې رمضان روژه ونیوه د هغه ګناهونه بخښل کیږي.','जो रमजान के रोजे ईमान से रखे उसके गुनाह माफ।','Ramazan orucunu iman ile tutanın günahları bağışlanır.','Кто держит пост в Рамадан с верой, тому прощаются грехи.','以信仰封斋月者，其以往的罪过将被宽恕。','信仰をもってラマダーンの断食をする者の罪は許される。') },

  { id: 'h009', arabic: 'لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ', narrator: 'حضرت انس بن مالکؓ', source: 'صحیح البخاری', hadithNumber: '13', bookNumber: '2', category: 'social', tags: ['ایمان','بھائی','محبت'],
    translations: t('لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ','جب تک اپنے بھائی کے لیے وہی نہ چاہو جو اپنے لیے چاہتے ہو مومن نہیں۔','None of you truly believes until he loves for his brother what he loves for himself.','هیچ‌کس مؤمن نیست تا آنچه برای خود می‌خواهد برای برادرش بخواهد.','কেউ মুমিন হতে পারবে না যতক্ষণ ভাইয়ের জন্য তাই চায় যা নিজের জন্য চায়।','ڪو به ايماندار نه ٿيندو جيستائين پنهنجي ڀاءُ لاءِ اهو نه چاهي.','هیچ‌کدام مؤمن نیستند تا برای برادرش آنچه می‌خواهد بخواهد.','هیڅوک به مؤمن نه وي تر هغه چې ورور ته هغه ونه غواړي.','कोई भी मोमिन नहीं जब तक भाई के लिए वही न चाहे।','Kardeşi için sevdiğini sevmedikçe mümin olamaz.','Никто не верующий, пока не желает брату того же, что и себе.','直到他爱兄弟如爱自己，才是真正的信士。','兄弟に自分のことを望むように望むまで信者ではない。') },

  { id: 'h010', arabic: 'الصَّبْرُ ضِيَاءٌ', narrator: 'حضرت ابو مالک اشعریؓ', source: 'صحیح مسلم', hadithNumber: '223', bookNumber: '2', category: 'patience', tags: ['صبر','روشنی'],
    translations: t('الصَّبْرُ ضِيَاءٌ','صبر روشنی ہے۔','Patience is a light.','صبر روشنایی است.','ধৈর্য একটি আলো।','صبر روشني آهي.','صبر روشنایی اِنت.','صبر رڼا ده.','धैर्य प्रकाश है।','Sabır bir nurdur.','Терпение — это свет.','耐心是一种光。','忍耐は光である。') },

  { id: 'h011', arabic: 'أَكْمَلُ الْمُؤْمِنِينَ إِيمَانًا أَحْسَنُهُمْ خُلُقًا', narrator: 'حضرت ابو ہریرہؓ', source: 'سنن الترمذی', hadithNumber: '1162', bookNumber: '12', category: 'character', tags: ['ایمان','اخلاق'],
    translations: t('أَكْمَلُ الْمُؤْمِنِينَ إِيمَانًا أَحْسَنُهُمْ خُلُقًا','ایمان میں سب سے کامل مومن وہ ہے جو اخلاق میں بہترین ہو۔','The most complete in faith are those with the best character.','کامل‌ترین مؤمنان کسانی‌اند که اخلاق بهتری دارند.','ঈমানে সবচেয়ে পরিপূর্ণ সে যার চরিত্র সর্বোত্তম।','ايمان ۾ سڀ کان ڪامل مومن اهو آهي جو اخلاق ۾ سٺو آهي.','کامل‌ترین مؤمنان کسانی انت که بهترین اخلاق دارند.','ترټولو بشپړ مؤمن هغه دی چې ده اخلاق ترټولو ښه وي.','ईमान में सबसे परिपूर्ण मोमिन जो चरित्र में सर्वश्रेष्ठ हो।','İmanca en mükemmel mümin, ahlakça en iyi olandır.','Наиболее совершенный в вере тот, кто лучше всех по характеру.','信仰最完整的信士是品格最好的人。','イーマンで最も完全な者は最も良い品性を持つ者。') },

  { id: 'h012', arabic: 'الْجَنَّةُ تَحْتَ أَقْدَامِ الأُمَّهَاتِ', narrator: 'مختلف روایات', source: 'مسند احمد', hadithNumber: '15557', bookNumber: '23', category: 'family', tags: ['جنت','ماں','والدین'],
    translations: t('الْجَنَّةُ تَحْتَ أَقْدَامِ الأُمَّهَاتِ','جنت ماؤں کے قدموں تلے ہے۔','Paradise lies beneath the feet of mothers.','بهشت زیر پای مادران است.','জান্নাত মায়েদের পায়ের নিচে।','جنت ماؤن جي قدمن هيٺ آهي.','جنت زیر پای مادران اِنت.','جنت د مورانو د پښو لاندې دی.','जन्नत माँओं के कदमों के नीचे है।','Cennet, annelerin ayakları altındadır.','Рай находится под ногами матерей.','天堂在母亲的脚下。','天国は母親たちの足の下にある。') },

  { id: 'h013', arabic: 'الطَّهُورُ شَطْرُ الإِيمَانِ', narrator: 'حضرت ابو مالک اشعریؓ', source: 'صحیح مسلم', hadithNumber: '223', bookNumber: '2', category: 'worship', tags: ['طہارت','پاکیزگی','ایمان'],
    translations: t('الطَّهُورُ شَطْرُ الإِيمَانِ','پاکیزگی نصف ایمان ہے۔','Cleanliness is half of faith.','پاکیزگی نیمی از ایمان است.','পবিত্রতা অর্ধেক ঈমান।','صفائي اڌ ايمان آهي.','پاکیزگی نصف ایمان اِنت.','پاکوالی د ایمان نیمه ده.','पवित्रता आधा ईमान है।','Temizlik imanın yarısıdır.','Чистота — половина веры.','清洁是信仰的一半。','清潔さは信仰の半分である。') },

  { id: 'h014', arabic: 'خَيْرُ النَّاسِ أَنْفَعُهُمْ لِلنَّاسِ', narrator: 'حضرت جابرؓ', source: 'المعجم الاوسط', hadithNumber: '5937', bookNumber: '6', category: 'social', tags: ['بہترین','انسان','خدمت'],
    translations: t('خَيْرُ النَّاسِ أَنْفَعُهُمْ لِلنَّاسِ','لوگوں میں سب سے بہتر وہ جو لوگوں کے لیے سب سے زیادہ فائدہ مند ہو۔','The best of people are those most beneficial to people.','بهترین مردم کسی است که بیشترین سود را به مردم می‌رساند.','মানুষের মধ্যে সর্বোত্তম সে যে মানুষের জন্য সবচেয়ে উপকারী।','ماڻهن مان بهترين اهو آهي جيڪو وڌيڪ فائدي مند هجي.','بهترین مردم کسانی انت که برای مردم بیشترین نفع دارند.','ترټولو غوره هغه دی چې خلکو ته ترټولو ګټور وي.','सबसे बेहतर वह जो लोगों के लिए सबसे लाभकारी हो।','İnsanların en hayırlısı insanlara en çok faydalı olandır.','Лучший — тот, кто приносит больше всего пользы людям.','最好的人是对人最有益的人。','人々の中で最も優れた者は最も有益な者。') },

  { id: 'h015', arabic: 'ابْدَأْ بِنَفْسِكَ', narrator: 'حضرت جابر بن عبداللہؓ', source: 'صحیح مسلم', hadithNumber: '997', bookNumber: '12', category: 'charity', tags: ['صدقہ','خود','شروع'],
    translations: t('ابْدَأْ بِنَفْسِكَ','پہلے اپنے آپ سے شروع کرو۔','Begin with yourself.','از خودت شروع کن.','নিজেকে দিয়ে শুরু করো।','پاڻ کان شروع ڪر.','از خودت شروع کن.','له ځانه پیل کوه.','पहले अपने आप से शुरू करो।','Kendinle başla.','Начни с себя.','从自己开始。','まず自分から始めなさい。') },

  { id: 'h016', arabic: 'مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ', narrator: 'حضرت ابو ہریرہؓ', source: 'صحیح البخاری', hadithNumber: '6018', bookNumber: '78', category: 'character', tags: ['گفتگو','خاموشی','ایمان'],
    translations: t('مَنْ كَانَ يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الآخِرِ فَلْيَقُلْ خَيْرًا أَوْ لِيَصْمُتْ','جو اللہ اور آخرت پر ایمان رکھتا ہو وہ اچھی بات کہے یا خاموش رہے۔','Whoever believes in Allah and the Last Day should say good or remain silent.','هرکس به الله ایمان دارد خیر بگوید یا ساکت باشد.','যে আল্লাহ ও আখেরাতে বিশ্বাস করে সে ভালো কথা বলুক বা চুপ থাকুক।','جيڪو الله ۽ آخرت تي يقين رکي، چڱو ڳالهائي يا خاموش رهي.','هرکه به الله ایمان دارد خیر بگوید یا خاموش باشد.','چا چې د الله باور لري ښه خبره وکړي یا خاموش پاته شي.','जो अल्लाह और आख़िरत पर विश्वास रखे अच्छी बात कहे या चुप रहे।','Allah\'a inanan hayır söylesin ya da sussun.','Верующий в Аллаха пусть говорит благое или молчит.','信仰安拉的人应说好话或保持沉默。','アッラーを信じる者は良いことを言うかまたは黙っていなさい。') },

  { id: 'h017', arabic: 'الْمُؤْمِنُ لِلْمُؤْمِنِ كَالْبُنْيَانِ يَشُدُّ بَعْضُهُ بَعْضًا', narrator: 'حضرت ابو موسیٰ اشعریؓ', source: 'صحیح البخاری', hadithNumber: '481', bookNumber: '8', category: 'social', tags: ['مومن','اتحاد','بھائی چارہ'],
    translations: t('الْمُؤْمِنُ لِلْمُؤْمِنِ كَالْبُنْيَانِ يَشُدُّ بَعْضُهُ بَعْضًا','ایک مومن دوسرے مومن کے لیے عمارت کی طرح ہے جو ایک دوسرے کو مضبوط کرتی ہے۔','A believer to another is like a building, each part supporting the other.','مؤمن نسبت به مؤمن دیگر مانند بنیان است که اجزایش یکدیگر را تقویت می‌کنند.','একজন মুমিন অন্য মুমিনের জন্য প্রাচীরের মতো, একে অপরকে শক্তিশালী করে।','هڪ مومن ٻئي مومن لاءِ عمارت جهڙو آهي.','مؤمن نسبت به مؤمن دیگر مانند بنیان اِنت.','یو مؤمن بل مؤمن لپاره د ودانۍ غوندې دی.','एक मोमिन दूसरे के लिए इमारत जैसा है।','Mü\'min mü\'mine kenetlenmiş bina gibidir.','Верующий для верующего подобен строению.','信士对信士如同建筑物，互相支撑。','信者は信者に対して建物のようで、互いを強化し合う。') },

  { id: 'h018', arabic: 'أَحَبُّ الأَعْمَالِ إِلَى اللَّهِ أَدْوَمُهَا وَإِنْ قَلَّ', narrator: 'حضرت عائشہؓ', source: 'صحیح البخاری', hadithNumber: '6464', bookNumber: '81', category: 'worship', tags: ['عبادت','مداومت','پسندیدہ'],
    translations: t('أَحَبُّ الأَعْمَالِ إِلَى اللَّهِ أَدْوَمُهَا وَإِنْ قَلَّ','اللہ کو سب سے زیادہ پسندیدہ عمل وہ ہے جو تھوڑا ہو لیکن مستقل ہو۔','The most beloved deeds to Allah are those most consistent, even if small.','محبوب‌ترین اعمال نزد الله آن‌هایی هستند که مداوم‌اند، هرچند کم.','আল্লাহর কাছে সবচেয়ে প্রিয় কাজ যা ছোট হলেও ধারাবাহিক।','الله کي سڀ کان وڌيڪ پسنديدو عمل اهو آهي جيڪو مستقل هجي.','محبوب‌ترین اعمال نزد الله آن‌هایی انت که مداوم‌اند.','د الله سره ترټولو خوښ عمل هغه دی چې مستقل وي.','अल्लाह को सबसे प्रिय कर्म वह है जो थोड़ा हो लेकिन नियमित हो।','Allah\'a en sevimli ameller, az da olsa devamlı olanlardır.','Самые любимые Аллахом дела — самые постоянные, пусть и малые.','安拉最喜爱的行为是持之以恒的，即使是小的。','アッラーが最も好む行いは小さくても継続的なものである。') },

  { id: 'h019', arabic: 'إِنَّ مِنْ أَكْبَرِ الْكَبَائِرِ أَنْ يَلْعَنَ الرَّجُلُ وَالِدَيْهِ', narrator: 'حضرت عبداللہ بن عمروؓ', source: 'صحیح البخاری', hadithNumber: '5973', bookNumber: '78', category: 'family', tags: ['والدین','گناہ','حقوق'],
    translations: t('إِنَّ مِنْ أَكْبَرِ الْكَبَائِرِ أَنْ يَلْعَنَ الرَّجُلُ وَالِدَيْهِ','کبیرہ گناہوں میں سے ہے کہ آدمی اپنے والدین پر لعن طعن کرے۔','Among the greatest sins is that a man curses his own parents.','از بزرگ‌ترین گناهان این است که انسان والدینش را لعن کند.','মহাপাপের একটি হলো নিজের বাবা-মাকে গালি দেওয়া।','وڏن گناهن مان آهي ته ماڻهو پنهنجن والدين کي لعنت ڪري.','از بزرگ‌ترین گناهان اِنت که انسان والدینش را لعن کند.','د لوی ګناهانو نه دا ده چې سړی خپل والدینو ته لعنت ووایي.','सबसे बड़े पापों में है कि व्यक्ति अपने माता-पिता को कोसे।','En büyük günahlardan biri kişinin ebeveynine lanet etmesidir.','Из величайших грехов — проклинать собственных родителей.','最大的罪之一是一个人诅咒他自己的父母。','最大の罪の一つは自分の親を呪うことである。') },

  { id: 'h020', arabic: 'رَحِمَ اللَّهُ رَجُلًا سَمَحًا إِذَا بَاعَ وَإِذَا اشْتَرَى وَإِذَا اقْتَضَى', narrator: 'حضرت جابر بن عبداللہؓ', source: 'صحیح البخاری', hadithNumber: '2076', bookNumber: '34', category: 'social', tags: ['تجارت','نرم دلی','رحمت'],
    translations: t('رَحِمَ اللَّهُ رَجُلًا سَمَحًا إِذَا بَاعَ وَإِذَا اشْتَرَى','اللہ اس شخص پر رحم فرمائے جو بیچتے، خریدتے اور تقاضا کرتے وقت نرمی سے کام لیتا ہے۔','Allah have mercy on one who is lenient when buying, selling and asking for repayment.','الله رحمت کند به کسی که در خرید و فروش و طلب کردن مسامحه می‌کند.','আল্লাহ দয়া করুন যে ক্রয়-বিক্রয়ে নরম।','الله رحم ڪري انهي تي جيڪو وڪڻڻ ۽ خريد ڪرڻ ۾ نرم هجي.','الله رحمت کند به کسی که در خرید و فروش مسامحه دارد.','الله رحمت وکړي هغه چاته چې پلور او اخستلو کې نرم وي.','अल्लाह उस पर दया करे जो खरीद-फरोख्त में नरम हो।','Allah, alışveriş ve talep etmede kolaylık gösteren kişiye merhamet etsin.','Да смилуется Аллах над тем, кто снисходителен в торговле.','愿安拉怜悯那些在买卖中宽容的人。','アッラーが売買で寛容な者に慈悲を与えますように。') },

  { id: 'h021', arabic: 'مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً مِنْ كُرَبِ الدُّنْيَا نَفَّسَ اللَّهُ عَنْهُ كُرْبَةً مِنْ كُرَبِ يَوْمِ الْقِيَامَةِ', narrator: 'حضرت ابو ہریرہؓ', source: 'صحیح مسلم', hadithNumber: '2699', bookNumber: '45', category: 'social', tags: ['مدد','قیامت','مومن'],
    translations: t('مَنْ نَفَّسَ عَنْ مُؤْمِنٍ كُرْبَةً','جو کسی مومن کی دنیا کی تکلیف دور کرے اللہ اس کی قیامت کی تکلیف دور فرمائے گا۔','Whoever relieves a believer\'s distress, Allah will relieve his distress on Judgment Day.','هرکس اندوه مؤمنی را در دنیا برطرف کند الله اندوه او را در قیامت برطرف کند.','যে মুমিনের দুঃখ দূর করে আল্লাহ কিয়ামতে তার কষ্ট দূর করবেন।','جيڪو مومن جي تڪليف دور ڪري، الله سندس قيامت جي تڪليف دور فرمائي.','هرکس مومنی را از گرفتاری برهاند الله در قیامت گرفتاری‌اش را برطرف کند.','چا چې د مومن تکلیف لرې کړ الله به د قیامت تکلیف یې لرې کړي.','जो किसी मोमिन की तकलीफ दूर करे अल्लाह उसकी क़यामत की तकलीफ दूर करेगा।','Bir mü\'minin sıkıntısını gideren Allah onun kıyamet sıkıntısını giderir.','Кто устраняет скорбь верующего, Аллах устранит его скорбь в День суда.','消除信士今世痛苦者，安拉将消除他后世的痛苦。','信者の苦しみを取り除く者のために、審判の日にアッラーが苦しみを取り除いてくださる。') },

  { id: 'h022', arabic: 'الْمُسْلِمُ أَخُو الْمُسْلِمِ لَا يَظْلِمُهُ وَلَا يُسْلِمُهُ', narrator: 'حضرت عبداللہ بن عمرؓ', source: 'صحیح البخاری', hadithNumber: '2442', bookNumber: '46', category: 'social', tags: ['مسلمان','ظلم','بھائی چارہ'],
    translations: t('الْمُسْلِمُ أَخُو الْمُسْلِمِ لَا يَظْلِمُهُ وَلَا يُسْلِمُهُ','مسلمان مسلمان کا بھائی ہے، نہ اس پر ظلم کرتا ہے نہ اسے دشمن کے حوالے کرتا ہے۔','A Muslim is the brother of a Muslim; he neither wrongs nor abandons him.','مسلمان برادر مسلمان است، نه بر او ظلم می‌کند نه او را تسلیم می‌کند.','মুসলমান মুসলমানের ভাই, সে তার উপর জুলুম করে না বা তাকে ছেড়ে দেয় না।','مسلمان مسلمان جو ڀاءُ آهي، نه ظلم ڪري نه سپرد ڪري.','مسلمان برادر مسلمان اِنت، نه بر او ظلم می‌کند نه رهایش می‌کند.','مسلمان د مسلمان ورور دی، نه پرې ظلم کوي نه يې پریږدي.','मुसलमान मुसलमान का भाई है, न उस पर अत्याचार करता है न उसे छोड़ता है।','Müslüman Müslümanın kardeşidir, ona zulmetmez ve onu terk etmez.','Мусульманин — брат мусульманина, он не угнетает его и не предаёт.','穆斯林是穆斯林的兄弟，不压迫他，也不抛弃他。','ムスリムはムスリムの兄弟であり、彼を虐げることも見捨てることもない。') },

  { id: 'h023', arabic: 'صَلُّوا كَمَا رَأَيْتُمُونِي أُصَلِّي', narrator: 'حضرت مالک بن الحویرثؓ', source: 'صحیح البخاری', hadithNumber: '631', bookNumber: '10', category: 'prayer', tags: ['نماز','سنت','طریقہ'],
    translations: t('صَلُّوا كَمَا رَأَيْتُمُونِي أُصَلِّي','نماز اس طرح پڑھو جیسے تم نے مجھے نماز پڑھتے دیکھا ہے۔','Pray as you have seen me pray.','همانگونه نماز بخوانید که مرا می‌بینید.','আমাকে যেভাবে নামাজ পড়তে দেখেছো সেভাবে পড়ো।','نماز اهڙي طرح پڙهو جيئن مون کي پڙهندو ڏٺو اٿئو.','نماز بخوانید همانطور که مرا می‌بینید نماز می‌خوانم.','لمونځ وکړئ لکه چې تاسو ما ته لمونځ کول لیدلي دي.','नमाज़ उसी तरह पढ़ो जैसे मुझे पढ़ते देखा है।','Beni namaz kılarken gördüğünüz gibi namaz kılın.','Совершайте молитву так, как видели меня молящимся.','按照你们看到我礼拜的方式礼拜。','私が礼拝しているのを見た通りに礼拝しなさい。') },

  { id: 'h024', arabic: 'أَفْضَلُ الصِّيَامِ بَعْدَ رَمَضَانَ شَهْرُ اللَّهِ الْمُحَرَّمُ', narrator: 'حضرت ابو ہریرہؓ', source: 'صحیح مسلم', hadithNumber: '1163', bookNumber: '13', category: 'worship', tags: ['روزہ','محرم','فضیلت'],
    translations: t('أَفْضَلُ الصِّيَامِ بَعْدَ رَمَضَانَ شَهْرُ اللَّهِ الْمُحَرَّمُ','رمضان کے بعد سب سے افضل روزے محرم کے روزے ہیں۔','The best fasting after Ramadan is fasting in the month of Muharram.','بهترین روزه پس از رمضان روزه ماه محرم است.','রমজানের পর সর্বোত্তম রোজা হলো মহররম মাসের রোজা।','رمضان کان پوءِ بهترين روزو محرم جو آهي.','بهترین روزه پس از رمضان ماه محرم اِنت.','د رمضان وروسته ترټولو ښه روژه د محرم مياشت ده.','रमजान के बाद सर्वश्रेष्ठ रोजे मुहर्रम में हैं।','Ramazan\'dan sonra en faziletli oruç Muharrem ayında tutulandır.','Лучший пост после Рамадана — в месяц Мухаррам.','斋月之后最佳的斋戒是安拉之月穆哈兰姆月。','ラマダーン後の最良の断食はムハッラム月の断食である。') },

  { id: 'h025', arabic: 'إِنَّ اللَّهَ لَا يَنْظُرُ إِلَى صُوَرِكُمْ وَأَمْوَالِكُمْ وَلَكِنْ يَنْظُرُ إِلَى قُلُوبِكُمْ وَأَعْمَالِكُمْ', narrator: 'حضرت ابو ہریرہؓ', source: 'صحیح مسلم', hadithNumber: '2564', bookNumber: '45', category: 'faith', tags: ['دل','نیت','اللہ'],
    translations: t('إِنَّ اللَّهَ لَا يَنْظُرُ إِلَى صُوَرِكُمْ وَأَمْوَالِكُمْ','اللہ تمہاری شکلوں اور مالوں کو نہیں دیکھتا بلکہ تمہارے دلوں اور اعمال کو دیکھتا ہے۔','Allah does not look at your faces or wealth, but at your hearts and deeds.','الله به چهره‌ها و اموال شما نمی‌نگرد بلکه به قلب‌ها و اعمال شما نظر دارد.','আল্লাহ তোমাদের চেহারা ও সম্পদ দেখেন না, তিনি হৃদয় ও কাজ দেখেন।','الله توهان جون صورتون ۽ مال نه ڏسي پر دل ۽ عمل ڏسي.','الله به چهره و اموال نمی‌نگرد بلکه به دل‌ها می‌نگرد.','الله ستاسو مخونه او شتمني نه ګوري، دی ستاسو زړونه او عمل ګوري.','अल्लाह तुम्हारे चेहरे और माल नहीं देखता बल्कि दिल और कर्म देखता है।','Allah görünüşünüze değil kalplerinize ve amellerinize bakar.','Аллах смотрит не на ваши лица и имущество, а на сердца и дела.','安拉不看你们的外貌和财富，而是看你们的心灵和行为。','アッラーはあなたたちの顔や財産を見ず、心と行いを見られる。') },

  { id: 'h026', arabic: 'اتَّقُوا الظُّلْمَ فَإِنَّ الظُّلْمَ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ', narrator: 'حضرت جابرؓ', source: 'صحیح مسلم', hadithNumber: '2578', bookNumber: '45', category: 'social', tags: ['ظلم','انصاف','قیامت'],
    translations: t('اتَّقُوا الظُّلْمَ فَإِنَّ الظُّلْمَ ظُلُمَاتٌ يَوْمَ الْقِيَامَةِ','ظلم سے بچو کیونکہ ظلم قیامت کے دن اندھیرے بن جائے گا۔','Beware of injustice, for injustice will be darkness on the Day of Judgment.','از ظلم بپرهیزید زیرا ظلم در روز قیامت تاریکی‌ها خواهد بود.','জুলুম থেকে বেঁচো, কারণ জুলুম কিয়ামতে অন্ধকার হয়ে যাবে।','ظلم کان بچو، ڇاڪاڻ ته ظلم قيامت تي اونداهه ٿي ويندو.','از ظلم بپرهیزید، ظلم در قیامت تاریکی‌ها خواهد بود.','له ظلمه ووېرېږئ، ظلم به د قیامت پر ورځ تیاره وي.','ज़ुल्म से बचो, क्योंकि ज़ुल्म कयामत में अंधेरा बन जाएगा।','Zulümden sakının, zira zulüm kıyamet gününde karanlıklar olacak.','Остерегайтесь несправедливости, ибо она станет тьмой в День суда.','警惕不公，因为不公在审判日将成为黑暗。','不正義を避けなさい。不正義は審判の日に暗闇となる。') },

  { id: 'h027', arabic: 'خَيْرُكُمْ خَيْرُكُمْ لِأَهْلِهِ وَأَنَا خَيْرُكُمْ لِأَهْلِي', narrator: 'حضرت عائشہؓ', source: 'سنن الترمذی', hadithNumber: '3895', bookNumber: '49', category: 'family', tags: ['گھروالے','بہترین','اہل وعیال'],
    translations: t('خَيْرُكُمْ خَيْرُكُمْ لِأَهْلِهِ','تم میں سب سے بہتر وہ ہے جو اپنے گھر والوں کے ساتھ بہترین ہو۔','The best of you is the best to his family.','بهترین شما کسی است که برای خانواده‌اش بهترین باشد.','তোমাদের মধ্যে সর্বোত্তম সে যে তার পরিবারের জন্য সর্বোত্তম।','توهان مان بهترين اهو آهي جيڪو پنهنجن گهروارن لاءِ بهترين هجي.','بهترین شما کسی اِنت که برای خانواده‌اش بهترین باشد.','ستاسو غوره هغه دی چې خپل کورنۍ ته ترټولو ښه وي.','तुम में सर्वश्रेष्ठ वह जो अपने परिवार के साथ सर्वोत्तम हो।','En hayırlınız ailesine en hayırlı olandır.','Лучший из вас тот, кто лучше всех с семьёй.','你们中最好的人是对家人最好的人。','最も良い者は家族に対して最も良い者である。') },

  { id: 'h028', arabic: 'الْحَيَاءُ مِنَ الإِيمَانِ', narrator: 'حضرت ابن عمرؓ', source: 'صحیح البخاری', hadithNumber: '24', bookNumber: '2', category: 'character', tags: ['حیا','ایمان','شرم'],
    translations: t('الْحَيَاءُ مِنَ الإِيمَانِ','حیا ایمان کا حصہ ہے۔','Modesty is part of faith.','حیا از ایمان است.','লজ্জাশীলতা ঈমানের অংশ।','حيا ايمان مان آهي.','حیا از ایمان اِنت.','حیا د ایمان برخه ده.','लज्जा ईमान का हिस्सा है।','Hayâ imandan bir şubedir.','Стыдливость — часть веры.','羞耻心是信仰的一部分。','恥じらいは信仰の一部である。') },

  { id: 'h029', arabic: 'مَا مَلأَ آدَمِيٌّ وِعَاءً شَرًّا مِنْ بَطْنٍ', narrator: 'حضرت مقدام بن معدیکربؓ', source: 'سنن الترمذی', hadithNumber: '2380', bookNumber: '37', category: 'etiquette', tags: ['کھانا','پیٹ','اعتدال'],
    translations: t('مَا مَلأَ آدَمِيٌّ وِعَاءً شَرًّا مِنْ بَطْنٍ','انسان نے پیٹ سے بدتر کوئی برتن نہیں بھرا۔','No human fills a vessel worse than his stomach.','هیچ انسانی ظرفی بدتر از شکم پر نکرده است.','মানুষ পেটের চেয়ে খারাপ কোনো পাত্র ভরেনি।','انسان پيٽ کان وڌيڪ خراب ڪو برتن نه ڀريو آهي.','هیچ انسانی ظرفی بدتر از شکم پر نکرده.','انسان د خپل ګیدۍ نه بدتره کومه لوښه نه ده ډکه کړه.','मनुष्य ने पेट से बुरा कोई बर्तन नहीं भरा।','Hiçbir insan karnından daha kötü bir kap doldurmamıştır.','Человек не наполнял сосуда хуже, чем желудок.','人类没有填满过比肚子更坏的容器。','人間は腹より悪い器を満たしたことはない。') },

  { id: 'h030', arabic: 'أَقْرَبُ مَا يَكُونُ الْعَبْدُ مِنْ رَبِّهِ وَهُوَ سَاجِدٌ', narrator: 'حضرت ابو ہریرہؓ', source: 'صحیح مسلم', hadithNumber: '482', bookNumber: '4', category: 'prayer', tags: ['سجدہ','قرب','نماز'],
    translations: t('أَقْرَبُ مَا يَكُونُ الْعَبْدُ مِنْ رَبِّهِ وَهُوَ سَاجِدٌ','بندہ اپنے رب کے سب سے قریب اس وقت ہوتا ہے جب وہ سجدے میں ہوتا ہے۔','The servant is closest to his Lord when he is in prostration.','بنده به پروردگارش نزدیک‌ترین حالت را در سجده دارد.','বান্দা তার প্রভুর সবচেয়ে কাছে থাকে যখন সে সিজদায় থাকে।','بندو پنهنجي رب جي سڀ کان ويجهو ان وقت ٿي جڏهن سجدي ۾ هجي.','بنده به پروردگارش نزدیک‌ترین حالت را در سجده دارد.','بنده د خپل رب سره ترټولو نږدې هغه وخت وي کله چې سجده کوي.','बंदा अपने रब के सबसे करीब उस वक्त होता है जब सजदे में होता है।','Kul rabbine en yakın secde halinde iken olur.','Раб ближе всего к своему Господу, когда находится в земном поклоне.','仆人与主最接近的时候是他在叩头的时候。','僕が主に最も近いのは伏礼をしているときである。') },

  { id: 'h031', arabic: 'تَبَسُّمُكَ فِي وَجْهِ أَخِيكَ صَدَقَةٌ', narrator: 'حضرت ابو ذرؓ', source: 'سنن الترمذی', hadithNumber: '1956', bookNumber: '27', category: 'charity', tags: ['مسکراہٹ','صدقہ','بھائی'],
    translations: t('تَبَسُّمُكَ فِي وَجْهِ أَخِيكَ صَدَقَةٌ','اپنے بھائی کے سامنے مسکرانا بھی صدقہ ہے۔','Your smile to your brother is charity.','لبخند زدن به روی برادرت صدقه است.','তোমার ভাইয়ের মুখের দিকে মুস্কি দেওয়া সদকা।','پنهنجي ڀاءُ جي منهن ۾ مُسڪرائڻ صدقو آهي.','لبخند زدن به روی برادرت صدقه اِنت.','خپل وروربه ته مسکا ورکول صدقه ده.','अपने भाई के सामने मुस्कुराना सदक़ा है।','Kardeşine gülümsemen sadakadır.','Улыбка в лицо брату — это садака.','对着你的兄弟微笑是慈善。','兄弟への微笑みは施しである。') },

  { id: 'h032', arabic: 'كُلُّ مَعْرُوفٍ صَدَقَةٌ', narrator: 'حضرت جابرؓ', source: 'صحیح البخاری', hadithNumber: '6021', bookNumber: '78', category: 'charity', tags: ['نیکی','صدقہ','معروف'],
    translations: t('كُلُّ مَعْرُوفٍ صَدَقَةٌ','ہر نیکی صدقہ ہے۔','Every act of goodness is charity.','هر خوبی صدقه است.','প্রতিটি ভালো কাজ সদকা।','هر نيڪي صدقو آهي.','هر خوبی صدقه اِنت.','هره نیکي صدقه ده.','हर नेकी सदक़ा है।','Her iyilik sadakadır.','Каждое благодеяние — это садака.','每一件善事都是慈善。','あらゆる善行は施しである。') },

  { id: 'h033', arabic: 'الْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ', narrator: 'حضرت ابو ہریرہؓ', source: 'صحیح البخاری', hadithNumber: '2989', bookNumber: '56', category: 'charity', tags: ['اچھی بات','صدقہ','گفتگو'],
    translations: t('الْكَلِمَةُ الطَّيِّبَةُ صَدَقَةٌ','اچھی بات کہنا بھی صدقہ ہے۔','A kind word is charity.','کلمه پاکیزه صدقه است.','ভালো কথা বলা সদকা।','سٺي ڳالهه به صدقو آهي.','کلمه پاکیزه صدقه اِنت.','ښه خبره هم صدقه ده.','अच्छी बात कहना भी सदक़ा है।','Güzel söz sadakadır.','Доброе слово — это садака.','说好话是慈善。','良い言葉は施しである。') },

  { id: 'h034', arabic: 'إِنَّ أَحَبَّكُمْ إِلَيَّ وَأَقْرَبَكُمْ مِنِّي مَجْلِسًا يَوْمَ الْقِيَامَةِ أَحَاسِنُكُمْ أَخْلَاقًا', narrator: 'حضرت جابر بن عبداللہؓ', source: 'سنن الترمذی', hadithNumber: '2018', bookNumber: '27', category: 'character', tags: ['محبت','قیامت','اخلاق'],
    translations: t('إِنَّ أَحَبَّكُمْ إِلَيَّ وَأَقْرَبَكُمْ مِنِّي مَجْلِسًا','قیامت کے دن مجھ سے سب سے زیادہ محبوب اور قریب وہ ہوگا جو اخلاق میں بہترین ہو۔','The most beloved and closest to me on Judgement Day will be those with the best character.','محبوب‌ترین شما نزد من در قیامت کسانی‌اند که بهترین اخلاق دارند.','কিয়ামতে আমার কাছে সবচেয়ে প্রিয় যে সর্বোত্তম চরিত্রের।','قيامت ۾ مون وٽ سڀ کان پيارو اهو هوندو جو اخلاق ۾ بهترين هجي.','محبوب‌ترین شما نزد من در قیامت کسانی انت که بهترین اخلاق دارند.','قیامت کې زما خوښ هغه به وي چې اخلاق یې ترټولو ښه وي.','क़यामत में मुझे सबसे प्रिय वह होगा जो चरित्र में सर्वश्रेष्ठ हो।','Kıyamette bana en sevimli en güzel ahlaka sahip olandır.','В Судный день самые любимые для меня — лучшие по нраву.','审判日离我最近最爱的是品德最好的人。','審判の日に私に最も愛される者は最も良い品性を持つ者である。') },

  { id: 'h035', arabic: 'مَنْ لَمْ يَشْكُرِ النَّاسَ لَمْ يَشْكُرِ اللَّهَ', narrator: 'حضرت ابو ہریرہؓ', source: 'سنن الترمذی', hadithNumber: '1954', bookNumber: '27', category: 'character', tags: ['شکر','انسان','اللہ'],
    translations: t('مَنْ لَمْ يَشْكُرِ النَّاسَ لَمْ يَشْكُرِ اللَّهَ','جو لوگوں کا شکریہ ادا نہیں کرتا وہ اللہ کا بھی شکر ادا نہیں کرتا۔','Whoever does not thank people does not thank Allah.','هرکس از مردم تشکر نکند از الله هم تشکر نکرده است.','যে মানুষের শুকরিয়া আদায় করে না সে আল্লাহরও শুকরিয়া আদায় করে না।','جيڪو ماڻهن جو شڪر نه ڪري اهو الله جو به شڪر نه ٿو ڪري.','هرکس از مردم تشکر نکند از الله هم تشکر نکرده.','چا چې د خلکو مننه ونه کړه د الله هم مننه یې ونه کړه.','जो लोगों का शुक्रिया नहीं अदा करता वह अल्लाह का भी शुक्रिया नहीं करता।','İnsanlara şükretmeyen Allah\'a da şükretmemiş olur.','Кто не благодарит людей, тот не благодарит Аллаха.','不感谢人的人也不感谢安拉。','人に感謝しない者はアッラーにも感謝しない。') },

  { id: 'h036', arabic: 'إِنَّ الرِّفْقَ لَا يَكُونُ فِي شَيْءٍ إِلَّا زَانَهُ', narrator: 'حضرت عائشہؓ', source: 'صحیح مسلم', hadithNumber: '2594', bookNumber: '45', category: 'character', tags: ['نرمی','حسن','سلوک'],
    translations: t('إِنَّ الرِّفْقَ لَا يَكُونُ فِي شَيْءٍ إِلَّا زَانَهُ','نرمی جس چیز میں بھی ہو اسے خوبصورت بنا دیتی ہے۔','Gentleness is not found in anything but it beautifies it.','مدارا در هر چیزی باشد آن را زیبا می‌کند.','নরমতা যেকোনো জিনিসে থাকলে তাকে সুন্দর করে।','نرمي جنهن شيءَ ۾ به هجي اها ان کي سهڻي ڪري ٿي.','مدارا در هر چیزی باشد آن را زیبا می‌کند.','نرمي چرته وي هلته ښکلا راولي.','नरमी जिस चीज में भी हो उसे सुंदर बना देती है।','Yumuşaklık her şeyi güzelleştirir.','Мягкость во всём украшает это.','温柔无论在什么事情上都能使之增添美丽。','穏やかさはどんなものにも美しさをもたらす。') },

  { id: 'h037', arabic: 'مَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا سَهَّلَ اللَّهُ لَهُ بِهِ طَرِيقًا إِلَى الْجَنَّةِ', narrator: 'حضرت ابو ہریرہؓ', source: 'صحیح مسلم', hadithNumber: '2699', bookNumber: '45', category: 'knowledge', tags: ['علم','جنت','راہ'],
    translations: t('مَنْ سَلَكَ طَرِيقًا يَلْتَمِسُ فِيهِ عِلْمًا','جو علم حاصل کرنے کی خاطر کوئی راستہ اختیار کرے اللہ اس کے لیے جنت کا راستہ آسان کر دیتا ہے۔','Whoever takes a path seeking knowledge, Allah eases his path to Paradise.','هرکس مسیری به جستجوی علم طی کند الله راه بهشت را برایش آسان می‌کند.','যে জ্ঞান অর্জনের পথে চলে আল্লাহ তার জন্য জান্নাতের পথ সহজ করেন।','جيڪو علم حاصل ڪرڻ لاءِ رستو اختيار ڪري، الله ان لاءِ جنت جو رستو آسان ڪري.','هرکس مسیری به جستجوی علم طی کند الله راه بهشت را آسان می‌کند.','چا چې د علم لپاره لار غوره کړه الله به د جنت لار ورته اسانه کړي.','जो ज्ञान के लिए रास्ता अपनाए अल्लाह उसके लिए जन्नत का रास्ता आसान करता है।','İlim yoluna giren için Allah cennete giden yolu kolaylaştırır.','Кто идёт путём знания, Аллах облегчает ему путь в рай.','走上求知之路，安拉为其开通天堂之路。','知識を求める道を歩む者のために、アッラーは天国への道を容易にする。') },

  { id: 'h038', arabic: 'اللَّهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا وَأَنْتَ تَجْعَلُ الْحَزْنَ إِذَا شِئْتَ سَهْلًا', narrator: 'حضرت انسؓ', source: 'صحیح ابن حبان', hadithNumber: '974', bookNumber: '3', category: 'faith', tags: ['دعا','آسانی','اللہ'],
    translations: t('اللَّهُمَّ لَا سَهْلَ إِلَّا مَا جَعَلْتَهُ سَهْلًا','اے اللہ! کوئی چیز آسان نہیں سوائے اس کے جسے تو آسان بنائے۔','O Allah! Nothing is easy except what You make easy.','پروردگارا! هیچ چیزی آسان نیست مگر آنچه تو آسان گردانی.','হে আল্লাহ! তুমি যা সহজ করো তাই সহজ।','يا الله! ڪجهه به آسان نه آهي سواءِ انهي جي جيڪو تون آسان ڪرين.','پروردگارا! هیچ چیزی آسان نیست مگر آنچه تو آسان گردانی.','یا الله! هیڅ شی اسان نه دی پرته له هغه چې ته یې اسانه کوې.','हे अल्लाह! कोई चीज आसान नहीं सिवाय उसके जिसे तू आसान कर दे।','Allah\'ım! Kolaylaştırdığın dışında hiçbir şey kolay değildir.','О Аллах! Нет ничего лёгкого, кроме того, что Ты сделаешь лёгким.','主啊！除了您使之容易的事物外，没有任何事是容易的。','主よ！あなたが容易にしてくださるもの以外に容易なものはありません。') },

  { id: 'h039', arabic: 'إِذَا مَاتَ الإِنْسَانُ انْقَطَعَ عَمَلُهُ إِلَّا مِنْ ثَلَاثَةٍ', narrator: 'حضرت ابو ہریرہؓ', source: 'صحیح مسلم', hadithNumber: '1631', bookNumber: '25', category: 'knowledge', tags: ['موت','صدقہ جاریہ','دعا'],
    translations: t('إِذَا مَاتَ الإِنْسَانُ انْقَطَعَ عَمَلُهُ إِلَّا مِنْ ثَلَاثَةٍ','جب انسان مر جاتا ہے تو اس کے اعمال منقطع ہو جاتے ہیں سوائے تین کے: صدقہ جاریہ، علم جس سے نفع اٹھایا جائے، نیک اولاد جو دعا کرے۔','When a person dies his deeds cease except three: ongoing charity, beneficial knowledge, or a righteous child who prays for him.','وقتی انسان می‌میرد عملش قطع می‌شود مگر سه چیز: صدقه جاریه، علم نافع، فرزند صالح.','মানুষ মারা গেলে তার আমল বন্ধ হয় তিনটি ছাড়া: সদকায়ে জারিয়া, উপকারী জ্ঞান, নেক সন্তান।','جڏهن انسان مري وڃي ته سندس عمل بند ٿي وڃن سواءِ ٽن جي.','وقتی انسان می‌میرد عملش قطع می‌شود مگر سه: صدقه جاریه، علم نافع، فرزند صالح.','کله چې انسان مري نو د هغه عمل پاتې کیږي پرته له دریو.','जब इंसान मरता है तो तीन को छोड़कर उसके अमल बंद हो जाते हैं।','İnsan ölünce ameli üç dışında kesilir.','Когда человек умирает, его дела прекращаются, кроме трёх.','人死后行为中断，除了三件事。','人が死ぬと行いは三つを除いて途絶える。') },

  { id: 'h040', arabic: 'أَنَا عِنْدَ ظَنِّ عَبْدِي بِي', narrator: 'حضرت ابو ہریرہؓ', source: 'صحیح البخاری', hadithNumber: '7405', bookNumber: '97', category: 'faith', tags: ['اللہ','گمان','رحمت'],
    translations: t('أَنَا عِنْدَ ظَنِّ عَبْدِي بِي','میں اپنے بندے کے ساتھ اس کے گمان کے مطابق ہوں۔','I am as My servant thinks of Me.','من آنچنانم که بنده‌ام گمان می‌کند.','আমি আমার বান্দার ধারণা অনুযায়ী তার সাথে আচরণ করি।','آءُ پنهنجي بندي جي گمان موجب سندس سان آهيان.','من آنچنانم که بنده‌ام گمان می‌کند.','زه د خپل بنده سره د هغه د ګومان سره سم يم.','मैं अपने बंदे के गुमान के मुताबिक उसके साथ हूँ।','Ben kulumun zannına göreyim.','Я таков, каким Меня представляет Мой раб.','我与我仆人对我的想法一致。','私は僕の私についての考えに従っている。') },

  { id: 'h041', arabic: 'بَلِّغُوا عَنِّي وَلَوْ آيَةً', narrator: 'حضرت عبداللہ بن عمروؓ', source: 'صحیح البخاری', hadithNumber: '3461', bookNumber: '60', category: 'knowledge', tags: ['تبلیغ','قرآن','علم'],
    translations: t('بَلِّغُوا عَنِّي وَلَوْ آيَةً','میری طرف سے پہنچاؤ خواہ ایک آیت ہی ہو۔','Convey from me, even if it is one verse.','از من ابلاغ کنید ولو یک آیه.','আমার পক্ষ থেকে পৌঁছে দাও একটি আয়াত হলেও।','مون وٽان پهچايو خواه هڪ آيت هجي.','از من ابلاغ کنید ولو یک آیه باشد.','زما له خوا رسوئ که یوه آیت هم وي.','मेरी तरफ से पहुँचाओ चाहे एक आयत ही क्यों न हो।','Benden tebliğ edin, bir ayet de olsa.','Передавайте от меня, пусть даже один аят.','替我传达，哪怕一节经文。','私から伝えなさい、一節だけでも。') },

  { id: 'h042', arabic: 'الْيَدُ الْعُلْيَا خَيْرٌ مِنَ الْيَدِ السُّفْلَى', narrator: 'حضرت حکیم بن حزامؓ', source: 'صحیح البخاری', hadithNumber: '1429', bookNumber: '24', category: 'charity', tags: ['دینے والا','لینے والا','صدقہ'],
    translations: t('الْيَدُ الْعُلْيَا خَيْرٌ مِنَ الْيَدِ السُّفْلَى','اوپر والا ہاتھ نیچے والے ہاتھ سے بہتر ہے (دینے والا لینے والے سے بہتر ہے)۔','The upper hand is better than the lower hand (the giving hand is better than the receiving hand).','دست بالا بهتر از دست پایین است (دهنده بهتر از گیرنده).','উপরের হাত নিচের হাতের চেয়ে ভালো (দানকারী গ্রহণকারীর চেয়ে ভালো)।','مٿيون هٿ هيٺئين هٿ کان بهتر آهي (ڏيڻ وارو وٺڻ واري کان بهتر).','دست بالا بهتر از دست پایین اِنت.','پورتنی لاس ښکتني لاس نه غوره دی.','ऊपर वाला हाथ नीचे वाले हाथ से बेहतर है।','Üstteki el alttaki elden hayırlıdır.','Рука дающего лучше руки берущего.','上手胜于下手（给予的手胜于接受的手）。','上の手は下の手より良い（施す手は受け取る手より良い）。') },

  { id: 'h043', arabic: 'إِنَّ مِنَ الشِّعْرِ حِكْمَةً', narrator: 'حضرت ابی بن کعبؓ', source: 'صحیح البخاری', hadithNumber: '6145', bookNumber: '78', category: 'knowledge', tags: ['حکمت','شعر','علم'],
    translations: t('إِنَّ مِنَ الشِّعْرِ حِكْمَةً','شاعری میں بھی حکمت ہوتی ہے۔','Indeed in poetry there is wisdom.','در شعر هم حکمت وجود دارد.','কবিতায়ও জ্ঞান রয়েছে।','شاعريءَ ۾ به حڪمت آهي.','در شعر هم حکمت وجود دارد.','شعر کې هم حکمت وي.','शायरी में भी हिकमत होती है।','Şiirde de hikmet vardır.','В поэзии тоже есть мудрость.','诗歌中也有智慧。','詩の中にも知恵がある。') },

  { id: 'h044', arabic: 'آكُلُ كَمَا يَأْكُلُ الْعَبْدُ وَأَجْلِسُ كَمَا يَجْلِسُ الْعَبْدُ', narrator: 'حضرت عائشہؓ', source: 'سنن ابی داؤد', hadithNumber: '3773', bookNumber: '28', category: 'etiquette', tags: ['عاجزی','کھانا','تواضع'],
    translations: t('آكُلُ كَمَا يَأْكُلُ الْعَبْدُ وَأَجْلِسُ كَمَا يَجْلِسُ الْعَبْدُ','میں ایسے کھاتا ہوں جیسے غلام کھاتا ہے اور ایسے بیٹھتا ہوں جیسے غلام بیٹھتا ہے۔','I eat like a servant eats and sit like a servant sits.','مثل یک بنده غذا می‌خورم و مثل یک بنده می‌نشینم.','আমি একজন দাসের মতো খাই এবং দাসের মতো বসি।','آءُ ائين کائيندو آهيان جيئن غلام کائيندو آهي.','مثل یک بنده غذا می‌خورم و مثل یک بنده می‌نشینم.','زه داسې خورم لکه چې بنده خوري او داسې کښینم لکه بنده.','मैं ऐसे खाता हूँ जैसे गुलाम खाता है।','Kul gibi yer kul gibi otururum.','Я ем как раб и сижу как раб.','我像仆人那样吃，像仆人那样坐。','私は奴隷のように食べ、奴隷のように座る。') },

  { id: 'h045', arabic: 'لَا تَحْقِرَنَّ مِنَ الْمَعْرُوفِ شَيْئًا وَلَوْ أَنْ تَلْقَى أَخَاكَ بِوَجْهٍ طَلْقٍ', narrator: 'حضرت ابو ذرؓ', source: 'صحیح مسلم', hadithNumber: '2626', bookNumber: '45', category: 'charity', tags: ['نیکی','مسکراہٹ','حقارت'],
    translations: t('لَا تَحْقِرَنَّ مِنَ الْمَعْرُوفِ شَيْئًا','کسی بھی نیکی کو حقیر مت سمجھو خواہ اپنے بھائی سے خندہ پیشانی سے ملنا ہی کیوں نہ ہو۔','Do not belittle any act of goodness, even meeting your brother with a cheerful face.','هیچ خوبی را کوچک نشمارید حتی اگر برادرت را با چهره‌ای خوشرو ملاقات کنی.','কোনো ভালো কাজকে ছোট মনে করো না, হাসি মুখে ভাইয়ের সাথে দেখা হলেও।','ڪنهن به نيڪيءَ کي حقير نه سمجهو.','هیچ خوبی را کوچک نشمارید حتی اگر برادرت را با خوشرویی ملاقات کنی.','هیڅ نیکي مه بده ګڼئ.','किसी भी नेकी को छोटा मत समझो।','Hiçbir iyiliği küçümseme.','Не пренебрегайте никаким добрым делом.','不要轻视任何善事。','いかなる善行も軽んじてはならない。') },

  { id: 'h046', arabic: 'كُنْ فِي الدُّنْيَا كَأَنَّكَ غَرِيبٌ أَوْ عَابِرُ سَبِيلٍ', narrator: 'حضرت عبداللہ بن عمرؓ', source: 'صحیح البخاری', hadithNumber: '6416', bookNumber: '81', category: 'faith', tags: ['دنیا','زہد','آخرت'],
    translations: t('كُنْ فِي الدُّنْيَا كَأَنَّكَ غَرِيبٌ أَوْ عَابِرُ سَبِيلٍ','دنیا میں اس طرح رہو جیسے کوئی اجنبی یا مسافر ہو۔','Be in this world as if you were a stranger or a traveler.','در دنیا مثل غریب یا مسافر باش.','দুনিয়ায় এমনভাবে থাকো যেন পরদেশী বা পথিক।','دنيا ۾ اهڙي طرح رهو جيئن ڪو پراڻو يا مسافر.','در دنیا مثل غریب یا مسافر باش.','دنیا کې داسې اوسه لکه چې پردیسی یا مسافر یې.','दुनिया में ऐसे रहो जैसे कोई अजनबी या मुसाफिर हो।','Dünyada bir yabancı veya yolcu gibi ol.','Будь в этом мире как чужестранец или путник.','在世上如同一个陌生人或过路人。','この世では見知らぬ人または旅人のように在れ。') },

  { id: 'h047', arabic: 'إِنَّ اللَّهَ رَفِيقٌ يُحِبُّ الرِّفْقَ فِي الأَمْرِ كُلِّهِ', narrator: 'حضرت عائشہؓ', source: 'صحیح البخاری', hadithNumber: '6927', bookNumber: '90', category: 'character', tags: ['نرمی','اللہ','رفق'],
    translations: t('إِنَّ اللَّهَ رَفِيقٌ يُحِبُّ الرِّفْقَ فِي الأَمْرِ كُلِّهِ','بے شک اللہ نرم خو ہے اور ہر کام میں نرمی کو پسند فرماتا ہے۔','Allah is gentle and loves gentleness in all matters.','الله لطیف است و در همه امور مدارا را دوست دارد.','আল্লাহ কোমল এবং সকল বিষয়ে কোমলতাকে ভালোবাসেন।','الله نرم آهي ۽ هر ڪم ۾ نرمي پسند ڪري ٿو.','الله لطیف است و مدارا را در همه امور دوست دارد.','الله نرم دی او هر چاره کې نرمي خوښوي.','अल्लाह नरम है और हर काम में नरमी पसंद फरमाता है।','Allah yumuşaktır ve her işte yumuşaklığı sever.','Аллах мягкий и любит мягкость во всех делах.','安拉温和，喜欢在一切事务中温和。','アッラーは温和で、すべての事において温和さを愛される。') },

  { id: 'h048', arabic: 'خَيْرُ الأَصْحَابِ عِنْدَ اللَّهِ خَيْرُهُمْ لِصَاحِبِهِ', narrator: 'حضرت عبداللہ بن عمروؓ', source: 'سنن الترمذی', hadithNumber: '1944', bookNumber: '27', category: 'social', tags: ['دوستی','ساتھی','بہترین'],
    translations: t('خَيْرُ الأَصْحَابِ عِنْدَ اللَّهِ خَيْرُهُمْ لِصَاحِبِهِ','اللہ کے نزدیک بہترین ساتھی وہ ہے جو اپنے ساتھی کے لیے بہترین ہو۔','The best companion in the sight of Allah is the best to his companion.','بهترین دوستان نزد الله کسی است که برای دوستش بهترین باشد.','আল্লাহর কাছে সর্বোত্তম সঙ্গী যে তার সঙ্গীর জন্য সর্বোত্তম।','الله وٽ بهترين ساٿي اهو آهي جيڪو پنهنجي ساٿيءَ لاءِ بهترين هجي.','بهترین دوستان نزد الله کسی اِنت که برای دوستش بهترین باشد.','د الله سره ترټولو ښه ملګری هغه دی چې خپل ملګري ته ښه وي.','अल्लाह के नजदीक बेहतरीन साथी वह है जो अपने साथी के लिए बेहतरीन हो।','Allah katında en hayırlı dost, arkadaşına en hayırlı olandır.','Лучший сподвижник у Аллаха — тот, кто лучше всех к своему другу.','在安拉看来最好的朋友是对朋友最好的人。','アッラーのもとで最良の仲間は自分の仲間に最も良い者である。') },

  { id: 'h049', arabic: 'لَيْسَ الشَّدِيدُ بِالصُّرَعَةِ إِنَّمَا الشَّدِيدُ الَّذِي يَمْلِكُ نَفْسَهُ عِنْدَ الْغَضَبِ', narrator: 'حضرت ابو ہریرہؓ', source: 'صحیح البخاری', hadithNumber: '6114', bookNumber: '78', category: 'character', tags: ['غصہ','قوت','صبر'],
    translations: t('لَيْسَ الشَّدِيدُ بِالصُّرَعَةِ','طاقتور وہ نہیں جو پہلوانی میں جیتے بلکہ طاقتور وہ ہے جو غصے کے وقت اپنے آپ کو قابو میں رکھے۔','The strong man is not the wrestler but one who controls himself when angry.','قوی کسی نیست که در کشتی پیروز شود بلکه آن است که در هنگام خشم خود را مهار کند.','শক্তিশালী সে নয় যে কুস্তিতে জেতে, বরং যে রাগের সময় নিজেকে নিয়ন্ত্রণ করে।','طاقتور اهو نه آهي جيڪو پهلواني ۾ جيتي پر اهو آهي جيڪو غصي ۾ پاڻ کي ڪنٽرول ڪري.','قوی کسی نیست که در کشتی پیروز شود بلکه کسی است که در خشم خود را مهار کند.','قوي هغه نه دی چې د پنجې لپاره بریالی شي بلکه هغه دی چې غوسه کې پخپل واکمن وي.','ताकतवर वह नहीं जो पहलवानी में जीते बल्कि वह जो गुस्से में खुद को काबू रखे।','Güçlü güreşte galip gelen değil, öfke anında nefsine hâkim olandır.','Сильный не тот, кто побеждает в борьбе, а тот, кто владеет собой в гневе.','强者不是摔跤冠军，而是能在愤怒时控制自己的人。','強い者は相撲で勝つ者ではなく、怒りの時に自分を制御できる者である。') },

  { id: 'h050', arabic: 'اسْتَعِينُوا عَلَى الْحَوَائِجِ بِالْكِتْمَانِ', narrator: 'حضرت معاذ بن جبلؓ', source: 'المعجم الصغیر', hadithNumber: '295', bookNumber: '1', category: 'etiquette', tags: ['پردہ پوشی','راز','حاجت'],
    translations: t('اسْتَعِينُوا عَلَى الْحَوَائِجِ بِالْكِتْمَانِ','ضرورتوں کو چھپا کر ان کے پورا ہونے میں مدد لو (راز رکھو)۔','Seek help in fulfilling your needs by keeping them secret.','در تأمین نیازها از طریق پنهان کردن آن‌ها یاری بجویید.','প্রয়োজনগুলো গোপন রেখে সেগুলো পূরণে সাহায্য নাও।','ضرورتن کي لڪائي انهن جي پوري ٿيڻ ۾ مدد ورتو.','در تأمین نیازها با پنهان کردن آن‌ها یاری بجویید.','خپلې اړتیاوې پټولو سره د هغو د پوره کولو کې مرسته واخلئ.','ज़रूरतों को छुपा कर उनके पूरा होने में मदद लो।','İhtiyaçların gizli tutularak karşılanmasında yardım alın.','Ищите помощи в удовлетворении нужд через сохранение их в тайне.','通过保密来寻求实现需求的帮助。','秘密にしておくことで必要なものを叶える助けを得なさい。') },

  { id: 'h051', arabic: 'لَا حَسَدَ إِلَّا فِي اثْنَتَيْنِ رَجُلٌ آتَاهُ اللَّهُ مَالًا فَسُلِّطَ عَلَى هَلَكَتِهِ فِي الْحَقِّ وَرَجُلٌ آتَاهُ اللَّهُ الْحِكْمَةَ', narrator: 'حضرت عبداللہ بن مسعودؓ', source: 'صحیح البخاری', hadithNumber: '73', bookNumber: '3', category: 'knowledge', tags: ['حسد','علم','مال'],
    translations: t('لَا حَسَدَ إِلَّا فِي اثْنَتَيْنِ','حسد صرف دو جگہ جائز ہے: ایک وہ جسے مال دیا گیا اور وہ اسے حق میں خرچ کرے، دوسرا وہ جسے حکمت دی گئی۔','Envy is only allowed in two cases: one given wealth who spends it justly, one given wisdom.','حسد جز در دو مورد جایز نیست: کسی که مال داده شده و در حق مصرف کند، و کسی که حکمت داده شده.','হিংসা শুধু দুই ক্ষেত্রে বৈধ: যাকে সম্পদ দেওয়া হয়েছে সঠিক পথে ব্যয়ের জন্য, এবং যাকে জ্ঞান দেওয়া হয়েছে।','حسد صرف ٻن جڳهن تي جائز آهي.','حسد جز در دو مورد جایز نیست.','حسد یوازې دوو ځایونو کې جایز دی.','हसद सिर्फ दो जगह जायज़ है।','Haset sadece iki durumda meşrudur.','Зависть допустима лишь в двух случаях.','羡慕只在两种情况下允许。','羨望は二つの場合のみ許される。') },

  { id: 'h052', arabic: 'إِنَّ اللَّهَ كَتَبَ الإِحْسَانَ عَلَى كُلِّ شَيْءٍ', narrator: 'حضرت شداد بن اوسؓ', source: 'صحیح مسلم', hadithNumber: '1955', bookNumber: '34', category: 'character', tags: ['احسان','خوبی','جانور'],
    translations: t('إِنَّ اللَّهَ كَتَبَ الإِحْسَانَ عَلَى كُلِّ شَيْءٍ','بے شک اللہ نے ہر چیز میں احسان فرض کیا ہے۔','Allah has prescribed excellence in all things.','الله احسان را در همه چیز واجب کرده است.','নিশ্চয়ই আল্লাহ সব কিছুতে সৎকার্য ফরজ করেছেন।','الله هر شيءَ تي احسان فرض ڪيو آهي.','الله احسان را در همه چیز واجب کرده.','الله د هر شي سره احسان فرض کړی دی.','अल्लाह ने हर चीज़ में अच्छाई को फ़र्ज़ किया है।','Allah her şeyde ihsanı farz kılmıştır.','Аллах предписал благодеяние во всём.','安拉规定了对所有事物行善。','アッラーはすべての事において善行を定められた。') },

  { id: 'h053', arabic: 'أَفْضَلُ الصَّلَاةِ بَعْدَ الْفَرِيضَةِ صَلَاةُ اللَّيْلِ', narrator: 'حضرت ابو ہریرہؓ', source: 'صحیح مسلم', hadithNumber: '1163', bookNumber: '13', category: 'prayer', tags: ['تہجد','نماز','فضیلت'],
    translations: t('أَفْضَلُ الصَّلَاةِ بَعْدَ الْفَرِيضَةِ صَلَاةُ اللَّيْلِ','فرض نمازوں کے بعد سب سے افضل نماز رات کی نماز ہے (تہجد)۔','The best prayer after the obligatory is the night prayer (Tahajjud).','بهترین نماز پس از فریضه نماز شب است.','ফরজ নামাজের পর সর্বোত্তম নামাজ হলো রাতের নামাজ (তাহাজ্জুদ)।','فرض نماز کان پوءِ بهترين نماز رات جي نماز آهي.','بهترین نماز پس از فریضه نماز شب اِنت.','د فرض لمونځ وروسته ترټولو غوره لمونځ د شپې لمونځ دی.','फ़र्ज़ नमाज़ के बाद सबसे अफ़ज़ल नमाज़ तहज्जुद है।','Farz namazdan sonra en faziletli namaz gece namazıdır.','Лучшая молитва после обязательной — ночная молитва.','法定礼拜之后最佳的是夜礼拜。','義務礼拝の後で最良の礼拝は夜の礼拝（タハッジュド）である。') },

  { id: 'h054', arabic: 'مَنْ أَصْبَحَ مِنْكُمْ آمِنًا فِي سِرْبِهِ مُعَافًى فِي جَسَدِهِ عِنْدَهُ قُوتُ يَوْمِهِ فَكَأَنَّمَا حِيزَتْ لَهُ الدُّنْيَا', narrator: 'حضرت عبداللہ بن محصنؓ', source: 'سنن الترمذی', hadithNumber: '2346', bookNumber: '37', category: 'faith', tags: ['شکر','نعمت','سلامتی'],
    translations: t('مَنْ أَصْبَحَ مِنْكُمْ آمِنًا فِي سِرْبِهِ','جو صبح امن میں اٹھے، جسم میں تندرست ہو اور اس کے پاس ایک دن کا کھانا ہو، تو گویا پوری دنیا اس کو دے دی گئی۔','Whoever among you wakes up safe, healthy, and with food for the day has been given the whole world.','هرکس با امنیت، سلامتی و روزی یک روز بیدار شود گویا دنیا به او داده شده.','যে নিরাপদ, সুস্থ ও এক দিনের রিজিক নিয়ে সকাল করে, যেন তাকে গোটা দুনিয়া দেওয়া হলো।','جيڪو صبح امن ۾ اٿي، تندرست هجي ۽ هڪ ڏينهن جو کاڌو هجي، گويا پوري دنيا ان کي ڏني وئي.','هرکس با امنیت، سلامتی و روزی یک روز بیدار شود گویا دنیا به او داده شده.','چا چې سبا امن کې وکړه، روغ وي او یوه ورځ رزق ولري، ګویا ټوله دنیا ورکړل شوه.','जो सुबह अमन, सेहत और एक दिन के रोज़ी के साथ उठे, गोया पूरी दुनिया उसे दे दी गई।','Kim güvenli, sağlıklı ve günlük rızkıyla sabahlarsa sanki dünya ona verilmiş gibidir.','Кто встал в безопасности, здоровым и с едой на день, тому как будто дана вся дунья.','早晨安全、健康且有一天食物的人，仿佛整个世界都给了他。','安全に、健康に、一日分の食糧を持って朝を迎える者には全世界が与えられたようなものだ。') },

  { id: 'h055', arabic: 'حُبُّكَ الشَّيْءَ يُعْمِي وَيُصِمُّ', narrator: 'حضرت ابو داؤدؓ', source: 'سنن ابی داؤد', hadithNumber: '5130', bookNumber: '43', category: 'character', tags: ['محبت','عقل','انصاف'],
    translations: t('حُبُّكَ الشَّيْءَ يُعْمِي وَيُصِمُّ','کسی چیز سے محبت اندھا اور بہرا کر دیتی ہے۔','Love of something makes you blind and deaf.','دوست داشتن چیزی کور و کر می‌کند.','কোনো কিছুর প্রতি ভালোবাসা অন্ধ ও বধির করে দেয়।','ڪنهن شيءَ جي محبت انڌو ۽ ٻوڙو ڪري ٿي.','دوست داشتن چیزی کور و کر می‌کند.','د یو شي مینه ړوند او کوڼ کوي.','किसी चीज़ की मुहब्बत अंधा और बहरा कर देती है।','Bir şeyi sevmek seni kör ve sağır yapar.','Любовь к чему-либо делает тебя слепым и глухим.','爱一件事会让你盲目和耳聋。','何かへの愛はあなたを盲目にし、耳を聾にする。') },

  { id: 'h056', arabic: 'ارْحَمُوا مَنْ فِي الأَرْضِ يَرْحَمْكُمْ مَنْ فِي السَّمَاءِ', narrator: 'حضرت عبداللہ بن عمروؓ', source: 'سنن الترمذی', hadithNumber: '1924', bookNumber: '27', category: 'character', tags: ['رحمت','زمین','آسمان'],
    translations: t('ارْحَمُوا مَنْ فِي الأَرْضِ يَرْحَمْكُمْ مَنْ فِي السَّمَاءِ','زمین والوں پر رحم کرو آسمان والا تم پر رحم کرے گا۔','Show mercy to those on earth, the One in heaven will show mercy to you.','به زمینیان رحم کنید تا آسمانی به شما رحم کند.','পৃথিবীবাসীদের প্রতি দয়া করো, আকাশের অধিপতি তোমাদের প্রতি দয়া করবেন।','زمين وارن تي رحم ڪريو، آسمان وارو توهان تي رحم ڪندو.','به زمینیان رحم کنید تا آسمانی به شما رحم کند.','د ځمکو خلکو ته رحم وکړئ، آسمانی به درته رحم وکړي.','ज़मीन वालों पर रहम करो, आसमान वाला तुम पर रहम करेगा।','Yerdeki canlılara merhamet edin ki gökteki de size merhamet etsin.','Проявляйте милосердие к живущим на земле — Тот, Кто на небесах, проявит к вам.','怜悯地上的人，天上的主会怜悯你们。','地にいる者を憐れみなさい、天にいる方があなたたちを憐れんでくださる。') },

  { id: 'h057', arabic: 'الظُّلْمُ لَا يَدُومُ وَالْعَدْلُ خَيْرٌ مِنْهُ', narrator: 'روایت عام', source: 'صحیح مسلم', hadithNumber: '2578', bookNumber: '45', category: 'social', tags: ['ظلم','عدل','انصاف'],
    translations: t('الظُّلْمُ لَا يَدُومُ وَالْعَدْلُ خَيْرٌ مِنْهُ','ظلم دیرپا نہیں ہوتا اور انصاف اس سے بہتر ہے۔','Injustice does not last, and justice is better than it.','ظلم پایدار نیست و عدالت بهتر از آن است.','অত্যাচার টেকসই নয় এবং ন্যায়বিচার তার চেয়ে ভালো।','ظلم دير پائيندڙ نه هوندو آهي ۽ انصاف ان کان بهتر آهي.','ظلم پایدار نیست و عدالت بهتر است.','ظلم پاتې نه کیږي او انصاف تر هغه غوره دی.','ज़ुल्म टिकाऊ नहीं होता और इंसाफ उससे बेहतर है।','Zulüm kalıcı değildir, adalet ondan daha hayırlıdır.','Несправедливость не длится, справедливость лучше неё.','不公不持久，正义优于不公。','不正義は長続きせず、正義はそれより良い。') },

  { id: 'h058', arabic: 'مَنْ أَحَبَّ لِقَاءَ اللَّهِ أَحَبَّ اللَّهُ لِقَاءَهُ', narrator: 'حضرت عائشہؓ', source: 'صحیح البخاری', hadithNumber: '6507', bookNumber: '81', category: 'faith', tags: ['اللہ','ملاقات','محبت'],
    translations: t('مَنْ أَحَبَّ لِقَاءَ اللَّهِ أَحَبَّ اللَّهُ لِقَاءَهُ','جو اللہ سے ملنا پسند کرے اللہ بھی اس سے ملنا پسند کرتا ہے۔','Whoever loves to meet Allah, Allah loves to meet him.','هرکس دیدار الله را دوست داشته باشد الله هم دیدار او را دوست دارد.','যে আল্লাহর সাথে সাক্ষাৎ ভালোবাসে আল্লাহও তার সাথে সাক্ষাৎ ভালোবাসেন।','جيڪو الله سان ملڻ پسند ڪري، الله به ان سان ملڻ پسند ڪري.','هرکس دیدار الله را دوست داشته باشد الله هم دیدار او را دوست دارد.','چا چې د الله سره لیدل خوښ وي الله هم د هغه سره لیدل خوښوي.','जो अल्लाह से मिलना पसंद करे अल्लाह भी उससे मिलना पसंद करता है।','Allah ile buluşmayı seven Allah da onunla buluşmayı sever.','Кто любит встречу с Аллахом, Аллах любит встречу с ним.','谁爱与安拉相遇，安拉也爱与他相遇。','アッラーとの出会いを愛する者を、アッラーも愛される。') },

  { id: 'h059', arabic: 'إِنَّ صَلَاحَ أَوَّلِ هَذِهِ الأُمَّةِ بِالزُّهْدِ وَالْيَقِينِ', narrator: 'حضرت ابن مسعودؓ', source: 'مسند احمد', hadithNumber: '3672', bookNumber: '6', category: 'faith', tags: ['امت','زہد','یقین'],
    translations: t('إِنَّ صَلَاحَ أَوَّلِ هَذِهِ الأُمَّةِ بِالزُّهْدِ وَالْيَقِينِ','اس امت کے پہلے لوگوں کی اصلاح زہد اور یقین سے ہوئی۔','The righteousness of the first of this nation was through asceticism and certainty.','صلاح اولین این امت به زهد و یقین بود.','এই উম্মতের প্রথম মানুষদের সংশোধন হয়েছিল দুনিয়াত্যাগ ও দৃঢ়বিশ্বাসের মাধ্যমে।','هن امت جي پهرين ماڻهن جي اصلاح زهد ۽ يقين سان ٿي.','صلاح اولین این امت به زهد و یقین بود.','د دغه امت د اولینو خلکو اصلاح زهد او یقین وه.','इस उम्मत के पहले लोगों की इस्लाह ज़ुहद और यक़ीन से हुई।','Bu ümmetin öncekilerinin ıslahı zühd ve yakîn iledir.','Праведность первых этой уммы была через аскетизм и убеждённость.','这个民族早期人的美德在于淡泊和笃信。','この共同体の最初の者たちの正義は禁欲と確信によって達成された。') },

  { id: 'h060', arabic: 'تُعِيْنُ الرَّجُلَ فِي دَابَّتِهِ فَتَحْمِلُهُ عَلَيْهَا أَوْ تَرْفَعُ لَهُ عَلَيْهَا مَتَاعَهُ صَدَقَةٌ', narrator: 'حضرت ابو ہریرہؓ', source: 'صحیح البخاری', hadithNumber: '2989', bookNumber: '56', category: 'charity', tags: ['مدد','صدقہ','سواری'],
    translations: t('تُعِيْنُ الرَّجُلَ فِي دَابَّتِهِ','کسی آدمی کو اس کی سواری پر چڑھنے یا اس پر سامان رکھنے میں مدد کرنا بھی صدقہ ہے۔','Helping a man with his animal by lifting him onto it or loading his luggage is charity.','کمک کردن به مرد در سوار شدن یا بارگذاری بر چارپایش صدقه است.','কাউকে বাহনে উঠতে বা মালামাল রাখতে সাহায্য করা সদকা।','ڪنهن ماڻهوءَ کي سواريءَ تي چڙهڻ يا سامان رکڻ ۾ مدد ڪرڻ صدقو آهي.','کمک کردن به مرد در سوار شدن یا بارگذاری بر چارپایش صدقه اِنت.','یو سړي ته د سپرلۍ سره مرسته صدقه ده.','किसी को सवारी पर चढ़ने या सामान रखने में मदद करना सदक़ा है।','Birinin bineğine binmesine veya yüklemesine yardım etmek sadakadır.','Помочь человеку сесть на животное или погрузить вещи — садака.','帮助人骑上坐骑或装载行李也是慈善。','誰かが乗り物に乗るのを助けたり荷物を載せるのを助けるのは施しである。') },

  { id: 'h061', arabic: 'لَا تَغْضَبْ وَلَكَ الْجَنَّةُ', narrator: 'حضرت ابو درداءؓ', source: 'المعجم الاوسط', hadithNumber: '6542', bookNumber: '7', category: 'character', tags: ['غصہ','جنت','صبر'],
    translations: t('لَا تَغْضَبْ وَلَكَ الْجَنَّةُ','غصہ نہ کرو اور تمہارے لیے جنت ہے۔','Do not get angry and you will have Paradise.','خشم مگیر و بهشت از آن توست.','রাগ করো না এবং তোমার জন্য জান্নাত রয়েছে।','غصو نه ڪر ۽ توهان لاءِ جنت آهي.','خشم مگیر و بهشت از آن توست.','غوسه مه کوه او جنت دې ستا ده.','गुस्सा मत करो और तुम्हारे लिए जन्नत है।','Öfkelenme ve sana cennet var.','Не гневайся, и тебе будет рай.','不要生气，天堂就是你的。','怒らなければ天国があなたのものだ。') },

  { id: 'h062', arabic: 'مَثَلُ الْجَلِيسِ الصَّالِحِ وَالسَّوْءِ كَحَامِلِ الْمِسْكِ وَنَافِخِ الْكِيرِ', narrator: 'حضرت ابو موسیٰؓ', source: 'صحیح البخاری', hadithNumber: '2101', bookNumber: '34', category: 'social', tags: ['ساتھی','اچھا','برا'],
    translations: t('مَثَلُ الْجَلِيسِ الصَّالِحِ وَالسَّوْءِ كَحَامِلِ الْمِسْكِ وَنَافِخِ الْكِيرِ','اچھے ساتھی کی مثال مشک اٹھانے والے جیسی ہے اور برے ساتھی کی مثال بھٹی پھونکنے والے جیسی۔','A good companion is like a musk bearer; a bad one like a bellows blower.','دوست صالح مانند حامل مشک و دوست بد مانند دمنده کوره است.','ভালো সঙ্গী কস্তুরিবাহকের মতো এবং খারাপ সঙ্গী কামারের ভাটার মতো।','سٺو ساٿي مشڪ کڻڻ واري جهڙو ۽ برو ساٿي ڀٽي ڦوڪڻ واري جهڙو آهي.','دوست صالح مانند حامل مشک و دوست بد مانند دمنده کوره اِنت.','ښه ملګری د مشک د وړونکي غوندې او بد ملګری د چالبوکي غوندې دی.','अच्छे साथी की मिसाल मुश्क उठाने वाले जैसी और बुरे की भट्टी फूँकने वाले जैसी।','İyi arkadaş misk taşıyan gibi, kötü arkadaş körük üfleyen gibidir.','Хороший товарищ подобен носильщику мускуса, плохой — раздувающему кузнечный мех.','好朋友如携带麝香者，坏朋友如吹铁炉者。','良い仲間はムスクを運ぶ者のようで、悪い仲間は鍛冶場の風箱を吹く者のようだ。') },

  { id: 'h063', arabic: 'كُلُّ أَمْرٍ ذِي بَالٍ لَا يُبْدَأُ فِيهِ بِبِسْمِ اللَّهِ فَهُوَ أَجْذَمُ', narrator: 'حضرت ابو ہریرہؓ', source: 'مسند احمد', hadithNumber: '8856', bookNumber: '14', category: 'worship', tags: ['بسم اللہ','آغاز','برکت'],
    translations: t('كُلُّ أَمْرٍ ذِي بَالٍ لَا يُبْدَأُ فِيهِ بِبِسْمِ اللَّهِ فَهُوَ أَجْذَمُ','ہر اہم کام جو بسم اللہ کے بغیر شروع ہو وہ ناقص ہے۔','Every important matter that does not begin with Bismillah is deficient.','هر کار مهمی که با بسم الله شروع نشود ناقص است.','প্রতিটি গুরুত্বপূর্ণ কাজ যা বিসমিল্লাহ ছাড়া শুরু হয় তা অসম্পূর্ণ।','ڪو به اهم ڪم جيڪو بسم الله کان سواءِ شروع ٿئي، ناقص آهي.','هر کار مهمی که با بسم الله شروع نشود ناقص اِنت.','هر مهم چاره چې بسم الله پرته پیل شي نیمه ده.','हर अहम काम जो बिस्मिल्लाह के बिना शुरू हो वह अधूरा है।','Besmele ile başlanmayan önemli her iş nakıstır.','Любое важное дело, не начатое с именем Аллаха, является ущербным.','每件重要的事若不以安拉之名开始则是不完整的。','ビスミッラーで始まらない重要な事は不完全である。') },

  { id: 'h064', arabic: 'مَنْ يُرِدِ اللَّهُ بِهِ خَيْرًا يُفَقِّهْهُ فِي الدِّينِ', narrator: 'حضرت معاویہؓ', source: 'صحیح البخاری', hadithNumber: '71', bookNumber: '3', category: 'knowledge', tags: ['خیر','دین','فقہ'],
    translations: t('مَنْ يُرِدِ اللَّهُ بِهِ خَيْرًا يُفَقِّهْهُ فِي الدِّينِ','جس کے ساتھ اللہ بھلائی چاہتا ہے اسے دین کی سمجھ عطا فرماتا ہے۔','Whoever Allah wants good for, He gives him understanding of the religion.','هرکس که الله برای او خیر بخواهد درک دین را به او می‌دهد.','আল্লাহ যার কল্যাণ চান তাকে দ্বীনের জ্ঞান দেন।','جنهن سان الله بھلائي چاهي ٿو، ان کي دين جي سمجهه ڏئي ٿو.','هرکس که الله برای او خیر بخواهد درک دین را به او می‌دهد.','چا ته چې الله غواړي ښه وکړي هغه ته د دین پوهاوی ورکوي.','जिसके साथ अल्लाह भलाई चाहता है उसे दीन की समझ अता फ़रमाता है।','Allah kimin için hayır isterse onu dinde fakih kılar.','Кому Аллах желает блага, тому дарует понимание религии.','安拉欲使谁得益，就赐予他宗教知识。','アッラーが誰かに善を望む時、その者に宗教の知恵を与える。') },

  { id: 'h065', arabic: 'الدُّنْيَا سِجْنُ الْمُؤْمِنِ وَجَنَّةُ الْكَافِرِ', narrator: 'حضرت ابو ہریرہؓ', source: 'صحیح مسلم', hadithNumber: '2956', bookNumber: '53', category: 'faith', tags: ['دنیا','مومن','کافر'],
    translations: t('الدُّنْيَا سِجْنُ الْمُؤْمِنِ وَجَنَّةُ الْكَافِرِ','دنیا مومن کے لیے قید خانہ اور کافر کے لیے جنت ہے۔','The world is a prison for the believer and paradise for the disbeliever.','دنیا برای مؤمن زندان و برای کافر بهشت است.','দুনিয়া মুমিনের জন্য কারাগার এবং কাফিরের জন্য জান্নাত।','دنيا مومن لاءِ قيدخانو ۽ ڪافر لاءِ جنت آهي.','دنیا برای مؤمن زندان و برای کافر بهشت اِنت.','دنیا د مومن لپاره بندي خانه ده او د کافر لپاره جنت.','दुनिया मोमिन के लिए क़ैद और काफ़िर के लिए जन्नत है।','Dünya müminin zindanı, kâfirin cennetidir.','Мир — тюрьма для верующего и рай для неверующего.','世界是信士的监狱，不信道者的天堂。','この世は信者にとって牢獄であり、不信者にとって天国である。') },

  { id: 'h066', arabic: 'اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ', narrator: 'حضرت انسؓ', source: 'صحیح البخاری', hadithNumber: '2893', bookNumber: '56', category: 'faith', tags: ['دعا','غم','پناہ'],
    translations: t('اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْهَمِّ وَالْحَزَنِ','اے اللہ! میں فکر اور غم سے تیری پناہ مانگتا ہوں۔','O Allah! I seek refuge in You from worry and grief.','پروردگارا! از اندوه و غم به تو پناه می‌برم.','হে আল্লাহ! আমি চিন্তা ও দুঃখ থেকে তোমার কাছে আশ্রয় চাই।','يا الله! مان ڳڻتي ۽ غم کان تنهنجي پناهه گهران ٿو.','پروردگارا! از اندوه و غم به تو پناه می‌برم.','یا الله! زه له فکر او غمه ستا پناه غواړم.','हे अल्लाह! मैं फ़िक्र और ग़म से तेरी पनाह माँगता हूँ।','Allah\'ım! Senden sıkıntı ve kederden sığınırım.','О Аллах! Я прибегаю к Тебе от тревоги и горя.','主啊！我向您求庇护，免受忧愁和悲伤。','主よ！私は心配と悲しみからあなたに避難を求めます。') },

  { id: 'h067', arabic: 'مَنْ تَوَاضَعَ لِلَّهِ رَفَعَهُ اللَّهُ', narrator: 'حضرت ابو ہریرہؓ', source: 'صحیح مسلم', hadithNumber: '2588', bookNumber: '45', category: 'character', tags: ['تواضع','عاجزی','بلندی'],
    translations: t('مَنْ تَوَاضَعَ لِلَّهِ رَفَعَهُ اللَّهُ','جو اللہ کے لیے عاجزی اختیار کرے اللہ اسے بلند فرماتا ہے۔','Whoever humbles himself for Allah, Allah raises him.','هرکس به خاطر الله تواضع کند الله او را بالا می‌برد.','যে আল্লাহর জন্য বিনয়ী হয় আল্লাহ তাকে উঁচু করেন।','جيڪو الله لاءِ عاجز ٿئي، الله ان کي بلند ڪري ٿو.','هرکس به خاطر الله تواضع کند الله او را بالا می‌برد.','چا چې د الله لپاره عاجزي وکړه الله به یې لوړ کړي.','जो अल्लाह के लिए इंकसारी अपनाए अल्लाह उसे ऊँचा करता है।','Allah için alçakgönüllü olan Allah onu yükseltir.','Кто проявляет смирение ради Аллаха, Аллах возвышает его.','为安拉而谦卑者，安拉使其崇高。','アッラーのために謙遜する者を、アッラーは高められる。') },

  { id: 'h068', arabic: 'صِلْ مَنْ قَطَعَكَ وَأَعْطِ مَنْ حَرَمَكَ وَاعْفُ عَمَّنْ ظَلَمَكَ', narrator: 'حضرت عقبہ بن عامرؓ', source: 'مسند احمد', hadithNumber: '17452', bookNumber: '29', category: 'character', tags: ['صلہ رحمی','معافی','احسان'],
    translations: t('صِلْ مَنْ قَطَعَكَ وَأَعْطِ مَنْ حَرَمَكَ وَاعْفُ عَمَّنْ ظَلَمَكَ','جو تم سے تعلق توڑے اس سے تعلق جوڑو، جو تمہیں محروم رکھے اسے دو، جو تم پر ظلم کرے اسے معاف کرو۔','Connect with who cuts you off, give to who deprives you, and forgive who wrongs you.','با کسی که با تو قطع رابطه کرده ارتباط برقرار کن.','যে সম্পর্ক ছেদ করেছে তার সাথে সম্পর্ক জোড়ো।','جيڪو توهان سان تعلق ٽوڙي، ان سان ٻيهر ٻڌو.','با کسی که با تو قطع رابطه کرده ارتباط برقرار کن.','چا چې تا سره اړیکه پرې کړه هغه سره یې بیا وصل کړه.','जो तमसे संबंध तोड़े उससे जोड़ो, जो महरूम रखे उसे दो।','Seni kesen ile bağ kur, seni mahrum edene ver, sana zulmedeni affet.','Соединись с тем, кто разорвал, дай тому, кто лишил, прости того, кто обидел.','与断绝关系者重建联系，给予剥夺你的人，宽恕伤害你的人。','あなたを縁切りした者と縁を結び、あなたを拒んだ者に与え、あなたに不正をした者を許しなさい。') },

  { id: 'h069', arabic: 'قُلِ اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَاهْدِنِي وَعَافِنِي وَارْزُقْنِي', narrator: 'حضرت طارق بن اشیمؓ', source: 'صحیح مسلم', hadithNumber: '2697', bookNumber: '48', category: 'faith', tags: ['دعا','مغفرت','ہدایت'],
    translations: t('قُلِ اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَاهْدِنِي وَعَافِنِي وَارْزُقْنِي','کہو: اے اللہ! مجھے بخش دے، مجھ پر رحم فرما، مجھے ہدایت دے، مجھے عافیت دے اور مجھے رزق دے۔','Say: O Allah, forgive me, have mercy on me, guide me, grant me wellbeing, and provide for me.','بگو: خدایا مرا ببخش، رحم کن، هدایت کن، عافیت ده و روزی ده.','বলো: হে আল্লাহ! আমাকে ক্ষমা করো, দয়া করো, হিদায়াত দাও, সুস্থতা দাও ও রিজিক দাও।','چئو: يا الله! مون کي بخشي ڇڏ، رحم فرما، هدايت ڏي، عافيت ڏي ۽ رزق ڏي.','بگو: پروردگارا مرا ببخش، رحم کن، هدایت کن، عافیت و روزی بده.','ووایه: یا الله! زما بخښنه وکړه، رحم وکړه، هدایت راکه، روغتیا راکه، رزق راکه.','कहो: हे अल्लाह! मुझे बख्श दे, रहम फ़रमा, हिदायत दे, आफ़ियत दे, रोज़ी दे।','De ki: Allah\'ım! Beni bağışla, bana merhamet et, bana hidayet ver, bana afiyet ver, beni rızıklandır.','Говори: О Аллах! Прости меня, помилуй меня, направь меня, даруй мне благополучие и пропитание.','说：主啊！饶恕我，怜悯我，引导我，赐我安康，赐我衣食。','言いなさい：主よ、私を赦し、慈しみ、導き、健康を与え、生計を与えてください。') },

  { id: 'h070', arabic: 'نِعْمَتَانِ مَغْبُونٌ فِيهِمَا كَثِيرٌ مِنَ النَّاسِ الصِّحَّةُ وَالْفَرَاغُ', narrator: 'حضرت ابن عباسؓ', source: 'صحیح البخاری', hadithNumber: '6412', bookNumber: '81', category: 'faith', tags: ['صحت','وقت','نعمت'],
    translations: t('نِعْمَتَانِ مَغْبُونٌ فِيهِمَا كَثِيرٌ مِنَ النَّاسِ الصِّحَّةُ وَالْفَرَاغُ','دو نعمتیں ایسی ہیں جن میں بہت سے لوگ دھوکہ کھاتے ہیں: صحت اور فراغت۔','Two blessings in which many are deceived: health and free time.','دو نعمتی که بسیاری از مردم از آن غافل‌اند: سلامتی و فراغت.','দুটি নেয়ামত যাতে অনেকে প্রতারিত: স্বাস্থ্য ও অবসর।','ٻه نعمتون آهن جن ۾ گهڻا ماڻهو دهوڪو کائيندا آهن: صحت ۽ فرصت.','دو نعمتی که بسیاری از مردم از آن غافل‌اند: سلامتی و فراغت.','دوه نعمتونه دي چې ډیر خلک پکې لوبول شوي: روغتیا او فراغت.','दो नेमतें हैं जिनमें बहुत लोग धोखा खाते हैं: सेहत और फ़ुर्सत।','İki nimet var ki pek çok insan onlar konusunda aldanmaktadır: sağlık ve boş vakit.','Две блага, в которых многие обмануты: здоровье и свободное время.','两种恩典许多人受骗其中：健康和闲暇。','二つの恵みにおいて多くの人が欺かれている：健康と暇。') },

  { id: 'h071', arabic: 'إِنَّ أَعْظَمَ الذُّنُوبِ عِنْدَ اللَّهِ أَنْ يَلْقَاهُ بِهَا عَبْدٌ بَعْدَ الْكَبَائِرِ الَّتِي نَهَى عَنْهَا', narrator: 'حضرت ابو ہریرہؓ', source: 'سنن ابی داؤد', hadithNumber: '4902', bookNumber: '43', category: 'character', tags: ['گناہ','بدزبانی','لعنت'],
    translations: t('إِنَّ أَعْظَمَ الذُّنُوبِ عِنْدَ اللَّهِ أَنْ يَلْقَاهُ بِهَا عَبْدٌ','اللہ کے نزدیک سب سے بڑا گناہ یہ ہے کہ بندہ اس حال میں ملے کہ اس نے ان لوگوں کو برا بھلا کہا جنہوں نے اسے برا بھلا نہیں کہا۔','Among the greatest sins is that a person insults those who did not insult him.','بزرگ‌ترین گناهان این است که بنده‌ای با این گناه الله را ملاقات کند که به کسانی که به او بد نگفته‌اند بد گفته است.','সবচেয়ে বড় গুনাহগুলোর একটি হলো যে ব্যক্তি তাদের গালি দেয় যারা তাকে গালি দেয়নি।','اللہ وٽ اهو وڏو گناهه آهي ته بندو انهن کي برو ڀلو چوي جن هن کي نه چيو.','بزرگ‌ترین گناهان این اِنت که کسی را بد بگوید که به او بد نگفته.','له ترټولو لویو ګناهانو نه دا ده چې هغه چاته بد ووایي چې هغه یې بد نه دی ویلی.','सबसे बड़े गुनाहों में से एक है कि जिसने बुरा न कहा उसे बुरा कहे।','En büyük günahlardan biri kendisine kötü söylemeyene kötü demektir.','Среди величайших грехов — ругать тех, кто тебя не ругал.','最大的罪之一是骂那些没有骂他的人。','最大の罪の一つは、悪口を言っていない者に悪口を言うことである。') },

  { id: 'h072', arabic: 'مَنْ صَلَّى عَلَيَّ صَلَاةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْرًا', narrator: 'حضرت ابو ہریرہؓ', source: 'صحیح مسلم', hadithNumber: '408', bookNumber: '4', category: 'worship', tags: ['درود','فضیلت','نبی'],
    translations: t('مَنْ صَلَّى عَلَيَّ صَلَاةً صَلَّى اللَّهُ عَلَيْهِ بِهَا عَشْرًا','جو مجھ پر ایک بار درود پڑھے اللہ اس پر دس رحمتیں نازل فرماتا ہے۔','Whoever sends one prayer upon me, Allah sends ten prayers upon him.','هرکس یک بار بر من درود بفرستد الله ده رحمت بر او می‌فرستد.','যে একবার আমার উপর দরুদ পড়ে আল্লাহ তার উপর দশ রহমত নাযিল করেন।','جيڪو مون تي هڪ ڀيرو درود پڙهي، الله ان تي ڏهه رحمتون نازل ڪري.','هرکس یک بار بر من درود بفرستد الله ده رحمت بر او می‌فرستد.','چا چې ما ته یو ځل درود ولوست الله به ده ته لس رحمتونه نازل کړي.','जो मुझ पर एक बार दुरूद पढ़े अल्लाह उस पर दस रहमतें नाज़िल करता है।','Bana bir kere salat getirene Allah on kere salat getirir.','Кто пошлёт на меня один раз молитву, Аллах пошлёт на него десять.','向我祈祷一次，安拉向他祈祷十次。','私に一度祝福の祈りを送る者に、アッラーは十の恵みを与えられる。') },

  { id: 'h073', arabic: 'اللَّهُمَّ أَصْلِحْ لِي دِينِي الَّذِي هُوَ عِصْمَةُ أَمْرِي', narrator: 'حضرت ابو ہریرہؓ', source: 'صحیح مسلم', hadithNumber: '2720', bookNumber: '48', category: 'faith', tags: ['دعا','دین','دنیا','آخرت'],
    translations: t('اللَّهُمَّ أَصْلِحْ لِي دِينِي الَّذِي هُوَ عِصْمَةُ أَمْرِي','اے اللہ! میرے دین کی اصلاح فرما جو میرے معاملات کی حفاظت ہے۔','O Allah! Set right for me my religion which is the safeguard of my affairs.','خدایا دینم را که سپر کارهایم است اصلاح فرما.','হে আল্লাহ! আমার দ্বীনকে ঠিক করে দাও যা আমার কাজের রক্ষাকবচ।','يا الله! منهنجي دين جي اصلاح فرما جيڪو منهنجي معاملن جو محافظ آهي.','خدایا دینم را که سپر کارهایم است اصلاح فرما.','یا الله! زما دین سم کړه چې د زما چارو ساتونکی دی.','हे अल्लाह! मेरे दीन की इस्लाह फ़रमा जो मेरे मामलों का حفाज़ त है।','Allah\'ım! Benim için işlerimin dayanağı olan dinimin ıslahını sağla.','О Аллах! Исправь мою религию, которая является защитой моих дел.','主啊！为我端正宗教，它是我事务的保障。','主よ！私の宗教を正してください、それが私の事柄の保護です。') },

  { id: 'h074', arabic: 'إِذَا أَحَبَّ اللَّهُ عَبْدًا نَادَى جِبْرِيلَ إِنِّي أُحِبُّ فُلَانًا فَأَحِبَّهُ', narrator: 'حضرت ابو ہریرہؓ', source: 'صحیح البخاری', hadithNumber: '3209', bookNumber: '59', category: 'faith', tags: ['محبت','اللہ','جبریل'],
    translations: t('إِذَا أَحَبَّ اللَّهُ عَبْدًا نَادَى جِبْرِيلَ إِنِّي أُحِبُّ فُلَانًا فَأَحِبَّهُ','جب اللہ کسی بندے سے محبت کرتا ہے تو جبریل کو آواز دیتا ہے کہ میں فلاں سے محبت کرتا ہوں تم بھی اس سے محبت کرو۔','When Allah loves a servant He calls Jibreel saying: I love so-and-so, so love him.','وقتی الله بنده‌ای را دوست دارد جبریل را صدا می‌زند: من فلانی را دوست دارم پس او را دوست بدار.','আল্লাহ কোনো বান্দাকে ভালোবাসলে জিবরাইলকে ডেকে বলেন: আমি তাকে ভালোবাসি তুমিও তাকে ভালোবাসো।','جڏهن الله ڪنهن بندي سان پيار ڪري ته جبريل کي آواز ڏئي.','وقتی الله بنده‌ای را دوست دارد جبریل را صدا می‌زند.','کله چې الله یو بنده سره مینه وکړي جبریل ته غږ کوي.','जब अल्लाह किसी बंदे से मुहब्बत करता है जिब्रील को आवाज़ देता है।','Allah bir kulu sevince Cibrail\'i çağırır: Ben falancayı seviyorum sen de sev.','Когда Аллах полюбит раба, зовёт Джибрила: Я люблю такого-то, полюби его.','安拉爱一个仆人时，呼唤吉卜利勒：我爱某人，你也爱他。','アッラーが僕を愛するとジブリールを呼び：私はある者を愛する、あなたも愛しなさい。') },

  { id: 'h075', arabic: 'اتَّقُوا الْفِرَاسَةَ فَإِنَّ الْمُؤْمِنَ يَنْظُرُ بِنُورِ اللَّهِ', narrator: 'حضرت ابو سعید الخدریؓ', source: 'سنن الترمذی', hadithNumber: '3127', bookNumber: '44', category: 'faith', tags: ['فراست','ایمان','نور'],
    translations: t('اتَّقُوا الْفِرَاسَةَ فَإِنَّ الْمُؤْمِنَ يَنْظُرُ بِنُورِ اللَّهِ','مومن کی فراست سے ڈرو کیونکہ وہ اللہ کے نور سے دیکھتا ہے۔','Beware the insight of the believer for he sees with the light of Allah.','از فراست مومن بترسید زیرا او با نور الله می‌بیند.','মুমিনের দূরদৃষ্টি থেকে সাবধান থাকো, কারণ সে আল্লাহর নূরে দেখে।','مومن جي فراست کان ڊڄو، ڇاڪاڻ ته اهو الله جي نور سان ڏسي.','از فراست مومن بترسید زیرا او با نور الله می‌بیند.','د مومن له فراست وېرې، ځکه هغه د الله د نور سره ګوري.','मोमिन की फ़िरासत से डरो क्योंकि वह अल्लाह के नूर से देखता है।','Müminin ferasetinden korkun çünkü o Allah\'ın nuruyla bakar.','Остерегайтесь проницательности верующего, ибо он видит светом Аллаха.','警惕信士的洞察力，因为他以安拉的光看世界。','信者の洞察力を恐れなさい、彼はアッラーの光で見るからである。') },
];

